UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bde-en-179","language":"English","title":"Importance of Statistics in Economics","topic_slug":"importance-of-statistics-in-economics","definition":"Statistics is an essential tool in economics for the analysis and interpretation of economic data. The use of statistics in economics involves the collection of data, the presentation of data in tabular, diagrammatic, and graphic forms, and the analysis and interpretation of data. Statistics is used in economics to formulate policies to solve economic problems and to improve the standard of living of individuals and societies.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bde' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'importance-of-statistics-in-economics' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bdd-en-180","language":"English","title":"Total Revenue","topic_slug":"total-revenue","definition":"Total Revenue is the total income earned by a firm from selling a given quantity of output. TR = Price (P) × Quantity (Q) Under Perfect Competition: Price is constant (price taker), so TR increases linearly. Under Monopoly/Imperfect Competition: To sell more, price must be reduced, so TR first rises, reaches maximum, then falls.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bdd' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'total-revenue' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bdd-en-181","language":"English","title":"Average Revenue","topic_slug":"average-revenue","definition":"Average Revenue is the revenue earned per unit of output sold. AR = TR / Q = Price AR is always equal to price. The AR curve is the demand curve of the firm. - Under perfect competition: AR = constant (horizontal line) - Under monopoly: AR is downward sloping (demand curve)","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bdd' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'average-revenue' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bdd-en-182","language":"English","title":"Marginal Revenue","topic_slug":"marginal-revenue","definition":"Marginal Revenue is the additional revenue earned from selling one more unit of output. MR = ΔTR / ΔQ = TRn – TR(n-1) Relationship between AR and MR: - Under perfect competition: AR = MR (horizontal, constant price) - Under monopoly: MR < AR and MR falls twice as fast as AR When TR is maximum: MR = 0 When TR is falling: MR is negative","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bdd' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'marginal-revenue' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bdd-en-183","language":"English","title":"Revenue Relationships","topic_slug":"revenue-relationships","definition":"Market Structure AR MR Relation --- --- --- --- Perfect Competition Constant = AR AR = MR Monopoly Falling Below AR, Falling MR < AR Monopolistic Falling Below AR MR < AR TR, AR, MR under perfect competition: - TR rises linearly - AR = MR = constant Price TR, AR, MR under monopoly: - TR rises, reaches max when MR = 0, then falls - AR is downward demand curve - MR falls faster than AR (MR = AR - (ΔP/ΔQ × Q)) --- AHSEC HS 1st Year Economics – Revenue chapter.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bdd' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'revenue-relationships' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be2-en-184","language":"English","title":"Meaning of Statistics","topic_slug":"meaning-of-statistics","definition":"Statistics can be understood in two senses: Singular Sense (Science): Statistics refers to the science of collecting, organising, presenting, analysing, and interpreting numerical data. Plural Sense (Data): Statistics refers to numerical data itself — e.g., \"statistics of national income.\" Definition: Statistics is the science that deals with the collection, organisation, presentation, analysis, and interpretation of quantitative data to aid in decision-making. Characteristics of Statistics: - Data are aggregate of facts (not single observations) - Data are expressed numerically - Data are affected by multiple causes - Data are collected with a specific purpose - Data are comparable","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be2' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'meaning-of-statistics' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be2-en-185","language":"English","title":"Scope of Statistics","topic_slug":"scope-of-statistics","definition":"Statistics has a wide scope across various fields: In Economics: - National income estimation (GDP, NNP) - Index numbers (price indices, industrial production index) - Demand forecasting - Study of inflation, unemployment, poverty In Business: - Market research - Quality control - Financial analysis - Operations management In Government: - Census operations - Budget planning - Social welfare programmes In Research: - Scientific experiments - Social surveys - Policy evaluation Limitations of Statistics: 1. Only studies numerical phenomena 2. Does not study individual observations 3. Results are only approximately true 4. Can be misused (\"Lies, damned lies, and statistics\") 5. Requires expertise for proper interpretation","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be2' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'scope-of-statistics' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be2-en-186","language":"English","title":"Importance of Statistics in Economics","topic_slug":"importance-of-statistics-in-economics","definition":"Study of Economic Problems: Statistics help quantify and analyse economic issues like poverty, unemployment, and inflation. 2. Economic Planning: Government uses statistics for planning (e.g., Five-Year Plans in India used statistical data on production, income, population). 3. Economic Laws: Laws like Demand Law are verified using statistical data. 4. Business Decisions: Firms use market research statistics for pricing, production, and investment decisions. 5. International Comparisons: Per capita income, HDI, trade statistics allow comparison between countries. 6. Testing Economic Theories: Econometrics uses statistical tools to test and validate economic theories. 7. Policy Formulation: Government policies on taxation, subsidies, and welfare programmes are based on statistical analysis. --- AHSEC HS 1st Year Economics – Statistics in Economics chapter.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be2' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'importance-of-statistics-in-economics' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bdf-en-187","language":"English","title":"Meaning of Supply","topic_slug":"meaning-of-supply","definition":"Supply refers to the quantity of a good that a producer is willing and able to offer for sale at a given price, during a given time period. Supply represents the producer''s side of the market (as demand represents the consumer''s side).","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bdf' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'meaning-of-supply' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bdf-en-188","language":"English","title":"Determinants of Supply","topic_slug":"determinants-of-supply","definition":"Price of the good: Higher price → higher supply (main determinant) 2. Input prices: Rise in input prices → supply decreases (higher cost) 3. Technology: Better technology → more efficient → supply increases 4. Number of firms: More firms → market supply increases 5. Government policy: Taxes reduce supply; subsidies increase supply 6. Prices of related goods: If price of substitute good rises → supply of original falls (producer switches) 7. Expectations: If future prices expected to rise → present supply falls (hoarding)","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bdf' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'determinants-of-supply' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bdf-en-189","language":"English","title":"Law of Supply","topic_slug":"law-of-supply","definition":"The Law of Supply states that, other things being equal (ceteris paribus), as the price of a good rises, the quantity supplied also rises, and as price falls, quantity supplied falls. Direct (positive) relationship between price and quantity supplied. Reason: Higher prices mean higher profits → firms are motivated to produce more.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bdf' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'law-of-supply' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bdf-en-190","language":"English","title":"Short Run Supply Curve","topic_slug":"short-run-supply-curve","definition":"The supply curve shows the graphical relationship between price and quantity supplied. It slopes upward from left to right (positive slope), reflecting the law of supply. In the short run, some inputs are fixed, so the firm''s supply curve is its MC curve above the AVC curve (shut-down point).","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bdf' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'short-run-supply-curve' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bdf-en-191","language":"English","title":"Long Run Supply Curve","topic_slug":"long-run-supply-curve","definition":"In the long run: - All inputs are variable - Firms can enter and exit the industry - The long-run supply curve can be: - Upward sloping (increasing cost industry) - Horizontal (constant cost industry) - Downward sloping (decreasing cost industry — rare)","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bdf' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'long-run-supply-curve' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bdf-en-192","language":"English","title":"Price Elasticity of Supply","topic_slug":"price-elasticity-of-supply","definition":"Price Elasticity of Supply (PES) measures the responsiveness of quantity supplied to changes in price. Es = (% Change in Quantity Supplied) / (% Change in Price) Es = (ΔQs/Qs) / (ΔP/P) Since supply and price move in the same direction, Es is always positive. Types: - Perfectly Inelastic (Es = 0): Quantity supplied does not change with price (vertical supply curve) - Perfectly Elastic (Es = ∞): Suppliers supply any amount at a given price (horizontal) - Relatively Inelastic (Es 1): Quantity change price change (manufactured goods)","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bdf' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'price-elasticity-of-supply' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bdf-en-193","language":"English","title":"Measurement of Elasticity of Supply","topic_slug":"measurement-of-elasticity-of-supply","definition":"Percentage Method: Es = (ΔQs / Qs × 100) / (ΔP / P × 100) Example: Price rises from ₹10 to ₹12 (ΔP = 2), Quantity supplied rises from 200 to 260 (ΔQs = 60). Es = (60/200) / (2/10) = 0.3 / 0.2 = 1.5 (elastic supply) Factors affecting Elasticity of Supply: 1. Nature of the good: Perishables → inelastic; manufactured goods → elastic 2. Time period: Longer time → more elastic (more adjustment possible) 3. Factor mobility: More mobile factors → more elastic supply 4. Ease of production: Easy to ramp up production → elastic --- AHSEC HS 1st Year Economics – Supply chapter notes.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bdf' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'measurement-of-elasticity-of-supply' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bda-en-194","language":"English","title":"PERFECT COMPETITION: DEFINING FEATURES","topic_slug":"perfect-competition-defining-features","definition":"A perfectly competitive market has a large number of buyers and sellers. Each firm produces and sells a homogeneous product. Entry into the market as well as exit from the market are free for firms. Information is perfect. The existence of a large number of buyers and sellers means that each individual buyer and seller is very small compared to the size of the market. Homogenous products further mean that the product of each firm is identical. Free entry and exit mean that it is easy for firms to enter the market, as well as to leave it. Perfect information implies that all buyers and all sellers are completely informed about the price, quality, and other relevant details about the product, as well as the market.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bda' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'perfect-competition-defining-features' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bda-en-195","language":"English","title":"PRICE-TAKING BEHAVIOUR","topic_slug":"price-taking-behaviour","definition":"A price-taking firm believes that if it sets a price above the market price, it will be unable to sell any quantity of the good that it produces. On the other hand, should the set price be less than or equal to the market price, the firm can sell as many units of the good as it wants to sell. A buyer would obviously like to buy the good at the lowest possible price. However, a price-taking buyer believes that if she asks for a price below the market price, no firm will be willing to sell to her. On the other hand, should the price asked be greater than or equal to the market price, the buyer can obtain as many units of the good as she desires to buy.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bda' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'price-taking-behaviour' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bda-en-196","language":"English","title":"TOTAL REVENUE CURVE","topic_slug":"total-revenue-curve","definition":"Total revenue (TR) of the firm is defined as the market price of the good (p) multiplied by the firm''s output (g). TR = pxq The total revenue curve plots the quantity sold or output on the x-axis and the revenue earned on the y-axis. The total revenue curve is a straight line because p is constant. When the output is zero, the total revenue of the firm is also zero. The total revenue increases as the output goes up.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bda' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'total-revenue-curve' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bda-en-197","language":"English","title":"AVERAGE REVENUE CURVE","topic_slug":"average-revenue-curve","definition":"The average revenue (AR) of a firm is defined as total revenue per unit of output. AR = TR/q = p The average revenue curve is a horizontal straight line that cuts the y-axis at a height equal to p. The price line also depicts the demand curve facing a firm. The demand curve is perfectly elastic, meaning that a firm can sell as many units of the good as it wants to sell at price p.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bda' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'average-revenue-curve' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bda-en-198","language":"English","title":"MARGINAL REVENUE","topic_slug":"marginal-revenue","definition":"The marginal revenue (MR) of a firm is defined as the increase in total revenue for a unit increase in the firm''s output. MR = (pq,-pq,)/ (q,-q,) For the perfectly competitive firm, MR = P. The intuition for this result is that when a firm increases its output by one unit, this extra unit is sold at the market price.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bda' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'marginal-revenue' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bda-en-199","language":"English","title":"PROFIT MAXIMISATION","topic_slug":"profit-maximisation","definition":"A firm''s profit, denoted by π, is defined to be the difference between its total revenue (TR) and its total cost of production (TC). π = TR - TC For profits to be maximum, three conditions must hold at q: 1. The price, p, must equal MC. 2. Marginal cost must be non-decreasing at q. 3. For the firm to continue to produce, in the short run, price must be greater than the average variable cost (p AVC); in the long run, price must be greater than the average cost (p AC).","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bda' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'profit-maximisation' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bda-en-200","language":"English","title":"CONDITION 1: MR = MC","topic_slug":"condition-1-mr-mc","definition":"Profits are the difference between total revenue and total cost. Both total revenue and total cost increase as output increases. As long as the change in total revenue is greater than the change in total cost, profits will continue to increase. Therefore, we can conclude that as long as marginal revenue is greater than marginal cost, profits are increasing. By the same logic, as long as marginal revenue is less than marginal cost, profits will fall. It follows that for profits to be maximum, marginal revenue should equal marginal cost.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bda' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'condition-1-mr-mc' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bda-en-201","language":"English","title":"CONDITION 2: MC CANNOT SLOPE DOWNWARDS","topic_slug":"condition-2-mc-cannot-slope-downwards","definition":"Consider the second condition that must hold when the profit-maximising output level is positive. Why is it the case that the marginal cost curve cannot slope downwards at the profit-maximising output level? To answer this question, refer once again to Figure 4.3. Note that at output levels q and q,, the market price is equal to the marginal cost. However, at the output level q,, the marginal cost curve is downward sloping. We claim that q, cannot be a profit-maximising output level. Why? Observe that for all output levels slightly to the left of q,, the market price is lower than the marginal cost. But, the market price is p, the output level of a profit-maximising firm is q,, where MR = MC. Therefore, the marginal cost curve cannot slope downwards at the profit-maximising output level.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bda' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'condition-2-mc-cannot-slope-downwards' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bda-en-202","language":"English","title":"CONDITION 3: P > AVC (SHORT RUN) AND P > AC","topic_slug":"condition-3-p-avc-short-run-and-p-ac","definition":"For the firm to continue to produce, in the short run, price must be greater than the average variable cost (p AVC). In the long run, price must be greater than the average cost (p AC). This condition ensures that the firm can continue to produce and sell its output at a price that covers its costs.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bda' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'condition-3-p-avc-short-run-and-p-ac' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19facee3667f3ecc3bd8-en-203","language":"English","title":"Theory of Consumer Behaviour","topic_slug":"theory-of-consumer-behaviour","definition":"The consumer has to decide how to spend her income on different goods, which is called the problem of choice. The consumer wants to get a combination of goods that gives her maximum satisfaction. The ''likes'' of the consumer are also called ''preferences''. The consumer''s preferences and what she can afford to buy depend on prices of the goods and her income.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19facee3667f3ecc3bd8' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'theory-of-consumer-behaviour' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19facee3667f3ecc3bd8-en-204","language":"English","title":"Positive and Normative Economics","topic_slug":"positive-and-normative-economics","definition":"In economics, we try to analyse the different mechanisms and figure out the outcomes which are likely to result under each of these mechanisms. We also try to evaluate the mechanisms by studying how desirable the outcomes resulting from them are. A distinction is made between positive economic analysis and normative economic analysis depending on whether we are trying to figure out how a particular mechanism functions or we are trying to evaluate it. Positive economic analysis studies how the different mechanisms function, and normative economics tries to understand whether these mechanisms are desirable or not.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19facee3667f3ecc3bd8' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'positive-and-normative-economics' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19facee3667f3ecc3bd8-en-205","language":"English","title":"Microeconomics and Macroeconomics","topic_slug":"microeconomics-and-macroeconomics","definition":"Traditionally, the subject matter of economics has been studied under two broad branches: Microeconomics and Macroeconomics. In microeconomics, we study the behaviour of individual economic agents in the markets for different goods and services and try to figure out how prices and quantities of goods and services are determined through the interaction of individuals in these markets. In macroeconomics, we try to get an understanding of the economy as a whole by focusing our attention on aggregate measures such as total output, employment and aggregate price level.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19facee3667f3ecc3bd8' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'microeconomics-and-macroeconomics' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19facee3667f3ecc3bd8-en-206","language":"English","title":"Consumer Behaviour","topic_slug":"consumer-behaviour","definition":"The consumer has to decide how to spend her income on different goods, which is called the problem of choice. The consumer wants to get a combination of goods that gives her maximum satisfaction. The ''likes'' of the consumer are also called ''preferences''. The consumer''s preferences and what she can afford to buy depend on prices of the goods and her income.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19facee3667f3ecc3bd8' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'consumer-behaviour' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19facee3667f3ecc3bd8-en-207","language":"English","title":"Cardinal Utility Analysis","topic_slug":"cardinal-utility-analysis","definition":"Cardinal utility analysis assumes that level of utility can be expressed in numbers. Utility of a commodity is its want-satisfying capacity. The more the need of a commodity or the stronger the desire to have it, the greater is the utility derived from the commodity. Utility is subjective and different individuals can get different levels of utility from the same commodity.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19facee3667f3ecc3bd8' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'cardinal-utility-analysis' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19facee3667f3ecc3bd8-en-208","language":"English","title":"Measures of Utility","topic_slug":"measures-of-utility","definition":"Total Utility: Total utility of a fixed quantity of a commodity (TU) is the total satisfaction derived from consuming the given amount of some commodity x. Marginal Utility: Marginal utility (MU) is the change in total utility due to consumption of one additional unit of a commodity.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19facee3667f3ecc3bd8' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'measures-of-utility' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19facee3667f3ecc3bd8-en-209","language":"English","title":"Law of Diminishing Marginal Utility","topic_slug":"law-of-diminishing-marginal-utility","definition":"The marginal utility diminishes with increase in consumption of the commodity. The law of diminishing marginal utility states that marginal utility from consuming each additional unit of a commodity declines as its consumption increases, while keeping consumption of other commodities constant.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19facee3667f3ecc3bd8' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'law-of-diminishing-marginal-utility' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19facee3667f3ecc3bd8-en-210","language":"English","title":"Demand Curve","topic_slug":"demand-curve","definition":"Demand for a commodity x, apart from the price of x itself, depends on factors such as prices of other commodities, income of the consumer and tastes and preferences of the consumers. Demand curve is a graphic presentation of various quantities of a commodity that a consumer is willing to buy at different prices of the same commodity, while holding constant prices of other related commodities and income of the consumer.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19facee3667f3ecc3bd8' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'demand-curve' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3beb-en-211","language":"English","title":"The Roman Empire","topic_slug":"the-roman-empire","definition":"The Roman Empire at its height (1st-2nd century CE) stretched across three continents — Europe, Africa (North Africa), and Asia (West Asia) — from Britain in the northwest to Mesopotamia in the east. Key figures: - Augustus Caesar (27 BCE – 14 CE): First Roman Emperor; brought peace (Pax Romana) - Trajan (98-117 CE): Empire at its greatest extent - Hadrian (117-138 CE): Consolidated frontiers; built Hadrian''s Wall in Britain Capital: Rome; later Constantinople (founded 330 CE by Emperor Constantine).","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3beb' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'the-roman-empire' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3beb-en-212","language":"English","title":"Economy and Society of the Roman Empire","topic_slug":"economy-and-society-of-the-roman-empire","definition":"Economy: - Agrarian base (grain, olive oil, wine were main products) - Long-distance trade: Mediterranean trade connected Rome with India (spices, silk), East Africa (ivory, gold) - Currency: Standardised gold and silver coinage (denarius) - Roads: Over 85,000 km of paved roads for military and commercial movement Society: - Senatorial class: Wealthy landowners, governed provinces - Equestrian class: Wealthy merchants and administrators - Free citizens (plebeians): Farmers, artisans, traders - Freedmen: Former slaves who gained freedom - Slaves: Large proportion of the workforce","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3beb' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'economy-and-society-of-the-roman-empire' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3beb-en-213","language":"English","title":"Religion in the Roman Empire","topic_slug":"religion-in-the-roman-empire","definition":"Polytheistic religion: Romans worshipped many gods (Jupiter, Mars, Venus, Neptune — adapted from Greek religion). Emperor worship: Emperors were considered divine; emperor cult unified the empire. Christianity: - Jesus Christ (c. 4 BCE – 30 CE) preached in Judaea (Roman province) - Christianity spread throughout the empire despite persecution (Nero, Diocletian) - 313 CE: Edict of Milan — Emperor Constantine granted freedom of worship to Christians - 380 CE: Christianity became official religion of Roman Empire (Theodosius I)","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3beb' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'religion-in-the-roman-empire' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3beb-en-214","language":"English","title":"Slavery and Roman Society","topic_slug":"slavery-and-roman-society","definition":"Scale: Slaves constituted 30-40% of Italy''s population at the height of the Empire. Sources of slaves: Conquest (prisoners of war), piracy, birth (children of slaves). Functions: Agricultural labour (latifundia — large slave estates), domestic service, skilled crafts, mining (harshest conditions), gladiatorial combat. Slave revolts: - Spartacus Revolt (73-71 BCE): Led by slave Spartacus; 70,000 slaves; crushed by Crassus and Pompey. Freedmen: Freed slaves could become Roman citizens; some rose to prominence as merchants, artisans, and imperial administrators.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3beb' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'slavery-and-roman-society' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3beb-en-215","language":"English","title":"Decline of the Roman Empire","topic_slug":"decline-of-the-roman-empire","definition":"Multiple causes: 1. Military: Constant wars on borders; reliance on barbarian mercenaries; loss of discipline 2. Economic: Heavy taxation, debasement of currency, falling agricultural productivity, decline of trade 3. Political: Political instability — 235-284 CE (\"Crisis of the Third Century\"); 50+ emperors in 50 years 4. Disease: Antonine Plague (165-180 CE) and Plague of Cyprian (249-262 CE) killed millions 5. External pressures: Migrations and invasions of Germanic tribes (Visigoths, Vandals, Huns)","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3beb' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'decline-of-the-roman-empire' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3beb-en-216","language":"English","title":"The Late Roman Empire","topic_slug":"the-late-roman-empire","definition":"Diocletian (284-305 CE): Divided empire into Eastern and Western halves for administrative efficiency. Constantine (306-337 CE): Founded Constantinople (modern Istanbul) as eastern capital; converted to Christianity. Final division (395 CE): Empire permanently split into: - Western Roman Empire (capital: Ravenna/Rome) — fell 476 CE (Romulus Augustulus deposed by Odoacer) - Eastern Roman Empire (Byzantine) (capital: Constantinople) — survived until 1453 CE 476 CE: Fall of Western Roman Empire — traditional date for end of ancient world and beginning of Middle Ages in Europe. --- AHSEC HS 1st Year History – The Roman Empire (Theme 3, NCERT Class 11 Themes in World History).","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3beb' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'the-late-roman-empire' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bee-en-217","language":"English","title":"The Renaissance","topic_slug":"the-renaissance","definition":"The Renaissance (French: \"rebirth\") was a cultural and intellectual movement that began in Italy in the 14th century and spread across Europe by the 16th century. It represented a renewed interest in the classical learning of ancient Greece and Rome. Origins: Italy — particularly Florence, Venice, and Rome. Why Italy? - Remnants of Roman heritage were physically present - Wealthy city-states (Medici family in Florence) patronised arts - Trade with Byzantine Empire (which had preserved Greek texts) and the Islamic world Key features: - Emphasis on human potential (humanism) - Secular approach to knowledge - Revival of classical art and architecture - Scientific curiosity and observation","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bee' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'the-renaissance' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bee-en-218","language":"English","title":"Humanism and Classical Learning","topic_slug":"humanism-and-classical-learning","definition":"Humanism placed human beings (not God or the Church) at the centre of intellectual inquiry. Humanists: - Studied Greek and Latin classical texts - Valued reason, individualism, and earthly achievements - Believed education should develop the whole person (mind, body, morals) Key humanists: - Francesco Petrarch (1304-1374): \"Father of Humanism\"; revived Latin literature - Desiderius Erasmus (1469-1536): Christian humanist; criticised Church corruption; In Praise of Folly - Leonardo Bruni (1370-1444): History of Florence; civic humanism","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bee' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'humanism-and-classical-learning' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bee-en-219","language":"English","title":"Renaissance Art and Architecture","topic_slug":"renaissance-art-and-architecture","definition":"Visual arts: - Perspective: Linear perspective (3D illusion on 2D surface) — Brunelleschi, Alberti - Anatomical realism: Leonardo da Vinci''s anatomical drawings - Secular subjects: Not just religious themes; portraits, mythological scenes Key artists: - Leonardo da Vinci (1452-1519): Mona Lisa , The Last Supper ; painter, scientist, engineer - Michelangelo (1475-1564): David , Pietà , Sistine Chapel ceiling - Raphael (1483-1520): School of Athens - Botticelli (1445-1510): Birth of Venus Architecture: - Revival of classical elements: columns, arches, domes - Brunelleschi: Florence Cathedral dome - St. Peter''s Basilica, Rome: Michelangelo''s dome","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bee' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'renaissance-art-and-architecture' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bee-en-220","language":"English","title":"The Reformation","topic_slug":"the-reformation","definition":"The Protestant Reformation was a 16th-century movement to reform the Catholic Church. It ultimately split Western Christianity. Causes: - Church corruption: sale of indulgences, nepotism, worldly bishops - Humanist criticism of Church - Rising nationalism (German princes resented Papal authority) - Printing press spread reforming ideas rapidly Key figures: - Martin Luther (1483-1546): German monk; nailed 95 Theses to Wittenberg church door (1517); challenged sale of indulgences and Papal authority; translated Bible into German - John Calvin (1509-1564): Geneva; doctrine of predestination; established theocratic government - Henry VIII of England: Broke with Rome over divorce; established Church of England (Anglicanism) Result: Europe split between Catholics and Protestants; Wars of Religion followed.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bee' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'the-reformation' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bee-en-221","language":"English","title":"Counter-Reformation","topic_slug":"counter-reformation","definition":"The Counter-Reformation (Catholic Reformation) was the Church''s response to Protestantism: - Council of Trent (1545-1563): Reformed Church abuses while reaffirming Catholic doctrine - Society of Jesus (Jesuits): Founded by Ignatius of Loyola (1540); educated elite; missionary work in Americas, Asia (including India — Francis Xavier) - Inquisition: Strengthened to combat heresy - Index of Forbidden Books: List of banned publications","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bee' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'counter-reformation' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bee-en-222","language":"English","title":"Print Culture and its Impact","topic_slug":"print-culture-and-its-impact","definition":"Johannes Gutenberg (c. 1450): Invented movable type printing press in Germany. This revolutionised communication. Impact: 1. Spread of Reformation: Luther''s ideas spread rapidly through printed pamphlets and books 2. Vernacular languages: Bible translated into local languages → literacy spread; Latin''s monopoly broken 3. Scientific Revolution: Scientific knowledge could be shared and built upon rapidly 4. Standardisation of languages: Print standardised spelling and grammar 5. Rise of public opinion: Printing enabled criticism of Church and state Book production: Before printing: 20 million manuscripts in Europe; by 1500: 20 million printed books; by 1600: 200 million. --- AHSEC HS 1st Year History – Changing Cultural Traditions (Renaissance and Reformation, Theme 7 NCERT Class 11).","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bee' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'print-culture-and-its-impact' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bef-en-223","language":"English","title":"European Colonisation of North America","topic_slug":"european-colonisation-of-north-america","definition":"European powers — Spain, France, England, and the Netherlands — colonised North America from the late 15th century onwards. Timeline: - 1492: Columbus reaches the Americas (Caribbean) - 1607: First permanent English settlement at Jamestown, Virginia - 1620: Pilgrim Fathers found Plymouth Colony, Massachusetts - 17th-18th century: Thirteen British colonies established along the eastern seaboard Motivations for colonisation: - Economic: Trade, resources (fur, timber, land, gold) - Religious: Puritan settlers fleeing religious persecution in England - Political: Territorial expansion and rivalry between European powers","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bef' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'european-colonisation-of-north-america' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bef-en-224","language":"English","title":"Indigenous Peoples of North America","topic_slug":"indigenous-peoples-of-north-america","definition":"Before European arrival, North America was home to diverse Native American nations, each with distinct cultures, languages, and social organisations. Major groups: - Northeast: Iroquois Confederacy (Haudenosaunee) — highly developed political confederation - Southeast: Cherokee, Choctaw, Creek - Plains: Sioux, Cheyenne, Comanche — nomadic bison hunters (post-horse) - Southwest: Navajo, Hopi — agriculture in desert - Northwest Coast: Haida — fishing societies; totem poles Population (pre-contact): Estimates range from 7 to 18 million people in North America.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bef' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'indigenous-peoples-of-north-america' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bef-en-225","language":"English","title":"Colonisation and Disease","topic_slug":"colonisation-and-disease","definition":"Devastating epidemics were the most catastrophic consequence of European contact. Indigenous peoples had no immunity to European diseases. Diseases: Smallpox, measles, influenza, typhus. Mortality: Estimates suggest 50-90% of indigenous populations died within a century of contact. Some regions lost 90%+ of their population. Smallpox: The most deadly. Used sometimes deliberately (infected blankets given to Native Americans by British forces in 1763 — documented biological warfare). Demographic collapse: Weakened indigenous societies, making them more vulnerable to military conquest and dispossession.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bef' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'colonisation-and-disease' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bef-en-226","language":"English","title":"Resistance and Subjugation","topic_slug":"resistance-and-subjugation","definition":"Despite enormous suffering, indigenous peoples resisted colonisation through: Military resistance: - King Philip''s War (1675-78): Metacom (Wampanoag) led alliance against New England colonies; one of bloodiest colonial wars - Pontiac''s War (1763): Great Lakes tribes attacked British forts - Battle of Little Bighorn (1876): Sioux and Cheyenne defeated US 7th Cavalry (Custer''s Last Stand) Legal and diplomatic resistance: - Treaties (though most were violated by the US government) - Appeals to courts (Cherokee Nation vs. Georgia, 1831) Policies of subjugation: - Indian Removal Act (1830): Forced removal of Five Civilised Tribes to \"Indian Territory\" (Oklahoma) — Trail of Tears — 4,000+ Cherokee deaths - Reservation system: Confined indigenous peoples to restricted land - Boarding schools: Forcibly separated children from families; banned indigenous languages","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bef' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'resistance-and-subjugation' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bef-en-227","language":"English","title":"Impact on Indigenous Culture","topic_slug":"impact-on-indigenous-culture","definition":"Cultural destruction: - Loss of land → loss of traditional economies (hunting, fishing, farming) - Banning of traditional religions, ceremonies, languages in 19th-20th centuries - Boarding schools: \"Kill the Indian, save the man\" — forced assimilation policy Legacy: - Today, about 2% of the US population identifies as Native American (5.2 million people) - Reservations remain among the poorest communities in America - Ongoing struggles for land rights, sovereignty, and cultural preservation - Recognition of historical injustice: US government formal apologies in recent decades --- AHSEC HS 1st Year History – Displacing Indigenous Peoples (Theme 10, NCERT Class 11 Themes in World History).","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bef' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'impact-on-indigenous-culture' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bec-en-228","language":"English","title":"The Mongols and their World","topic_slug":"the-mongols-and-their-world","definition":"The Mongols were pastoral nomads of the Central Asian steppes. Their lifestyle was organised around: - Herding: Cattle, horses, sheep, goats - Mobility: Moved seasonally following pasture - Horses: Central to their military power - Ger (Yurt): Portable felt tent as dwelling Social organisation: Clans and tribes; kinship was the basis of loyalty. Alliances and conflicts between tribes were common before Mongol unification.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bec' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'the-mongols-and-their-world' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bec-en-229","language":"English","title":"Genghis Khan and the Mongol Empire","topic_slug":"genghis-khan-and-the-mongol-empire","definition":"Genghis Khan (born Temujin, c. 1162-1227): - Born into a minor Mongol clan - Lost his father to poison by rivals; endured poverty and captivity - Through military genius and political skill, united all Mongol tribes by 1206 - Proclaimed Genghis Khan (\"Universal Ruler\") at a great assembly (kuriltai) in 1206 Conquests: - China: Conquered northern China (Jin dynasty), also attacked Song China - Central Asia: Conquered Khwarazm Shah''s empire (modern Uzbekistan, Iran, Afghanistan) - Eastern Europe: Mongols reached Poland and Hungary (1241) By his death in 1227, Genghis Khan ruled the largest contiguous empire in history. Military innovations: - Highly mobile cavalry tactics - Psychological warfare and terror - Adopted siege technology from Chinese and Persian engineers - Sophisticated military organisation (decimal system: groups of 10, 100, 1000, 10,000)","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bec' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'genghis-khan-and-the-mongol-empire' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bec-en-230","language":"English","title":"Nature of Mongol Rule","topic_slug":"nature-of-mongol-rule","definition":"After Genghis Khan''s death, the empire was divided among his sons into four khanates: 1. Golden Horde (Russia/Central Asia) 2. Chagatai Khanate (Central Asia) 3. Ilkhanate (Persia/Iran) 4. Khanate of the Great Khan (China/Mongolia) → ruled by Kublai Khan Governance: - Initially destructive — cities destroyed, populations massacred (Baghdad 1258) - Later, Mongols adopted local cultures and administrative systems - Meritocracy — capable administrators from any background appointed - Religious tolerance — Mongols generally tolerated all religions Kublai Khan (1260-1294): Ruled China, founded Yuan dynasty; promoted trade and welcomed foreign visitors (Marco Polo visited his court).","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bec' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'nature-of-mongol-rule' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bec-en-231","language":"English","title":"Trade and Communication in Mongol Empire","topic_slug":"trade-and-communication-in-mongol-empire","definition":"The Mongol Empire created the Pax Mongolica (Mongol Peace) — a period of relative stability and security across Eurasia that facilitated: Silk Road revival: Long-distance trade between China and Europe flourished. Merchants, diplomats, and missionaries could travel safely. Relay stations (Yam system): A postal relay system with fresh horses every 40 km enabled rapid communication and allowed merchants to travel 400+ km per day. Cultural exchange: - Chinese technology (printing, gunpowder, paper money) spread westward - Islamic astronomy and mathematics reached China and Europe - Bubonic plague (Black Death) also spread along Mongol trade routes (1340s)","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bec' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'trade-and-communication-in-mongol-empire' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bec-en-232","language":"English","title":"Significance of Mongol Empire","topic_slug":"significance-of-mongol-empire","definition":"Connected East and West: The Silk Road''s safety under Mongol rule connected China, Central Asia, Iran, and Europe. 2. Cross-cultural exchange: Unprecedented movement of people, goods, and ideas. 3. Transmission of knowledge: Chinese printing and gunpowder reached Europe; Islamic science reached China. 4. Unintended consequences: Black Death (1347-1353) may have travelled via Mongol trade routes — killed 30-60% of Europe''s population. 5. Political impact: Destruction of Abbasid Caliphate (1258) ended Baghdad''s golden age; Mongol invasions reshaped Central Asian political landscape. --- AHSEC HS 1st Year History – Nomadic Empires (Theme 5, NCERT Class 11 Themes in World History).","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bec' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'significance-of-mongol-empire' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bf0-en-233","language":"English","title":"Modernisation and Different Paths","topic_slug":"modernisation-and-different-paths","definition":"Modernisation refers to the process of social, economic, and political transformation associated with industrialisation, urbanisation, scientific rationalism, and democracy. Different societies took different paths to modernisation. Key features of modernisation: - Industrialisation (shift from agriculture to manufacturing) - Urbanisation (people moving to cities) - Scientific and technological development - Democratic governance - Secular education In the 19th-20th centuries, Asian nations faced the challenge of modernising to resist Western colonial dominance.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bf0' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'modernisation-and-different-paths' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bf0-en-234","language":"English","title":"Meiji Restoration in Japan","topic_slug":"meiji-restoration-in-japan","definition":"Background: - Japan was under Tokugawa Shogunate (1600-1868) — isolated from the world (sakoku policy) - 1853: US Commodore Matthew Perry''s \"Black Ships\" forced Japan to open ports (unequal treaties) - Crisis of sovereignty → overthrow of Shogunate Meiji Restoration (1868): - Emperor Meiji (1868-1912) restored to power - Slogan: \"Enrich the Country, Strengthen the Military\" (fukoku kyōhei) - Slogan: \"Civilisation and Enlightenment\" (bunmei kaika) Reforms: - Political: Centralised modern state; Meiji Constitution (1889); elected parliament (Diet) - Economic: Industrialisation led by government; railways, telegraph, modern industries - Military: Universal conscription; modern army and navy (German model for army, British for navy) - Education: Universal primary education; modern universities; sent students abroad - Social: Western dress, calendars, customs adopted by elite; feudal class system abolished","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bf0' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'meiji-restoration-in-japan' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bf0-en-235","language":"English","title":"Japan''s Industrialisation","topic_slug":"japan-s-industrialisation","definition":"Japan industrialised rapidly from the 1870s-1890s, becoming Asia''s first industrial power. Government role: - Founded model factories - Subsidised key industries - Built infrastructure (railways, ports) - Educated technical workforce Zaibatsu: Large family-owned industrial conglomerates (Mitsubishi, Mitsui, Sumitomo) dominated Japanese industry. Results by 1900: - Major steel, shipbuilding, textile industries - Modern railways across Japan - Powerful army and navy Military victories: - Sino-Japanese War (1894-95): Japan defeated China; gained Taiwan and influence in Korea - Russo-Japanese War (1904-05): Japan defeated Russia — first Asian nation to defeat a European power; gained international recognition","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bf0' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'japan-s-industrialisation' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bf0-en-236","language":"English","title":"China''s Response to Modernisation","topic_slug":"china-s-response-to-modernisation","definition":"China''s situation: - After Opium Wars (1839-42, 1856-60), China was forced to sign unequal treaties - Concessions to Western powers; humiliating defeats - Qing dynasty (1644-1912) resisted fundamental reform Responses: - Self-Strengthening Movement (1860s-1895): \"Chinese learning for fundamental values, Western learning for practical use\" — adopted Western technology but rejected political reform; failed (exposed in 1895 Sino-Japanese War defeat) - Hundred Days'' Reform (1898): Emperor Guangxu''s radical reforms — blocked by Empress Dowager Cixi after 103 days - Boxer Rebellion (1900): Anti-foreign uprising suppressed by combined Western and Japanese forces Fall of Qing Dynasty (1911-12): Revolution led by Sun Yat-sen; Republic of China established.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bf0' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'china-s-response-to-modernisation' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bf0-en-237","language":"English","title":"Nationalism in East Asia","topic_slug":"nationalism-in-east-asia","definition":"Japanese nationalism: - Pan-Asian rhetoric (\"Asia for Asians\") combined with Japanese imperialism - Japan portrayed itself as liberating Asia from Western colonialism while actually colonising Korea (1910), China, and Southeast Asia Chinese nationalism: - Sun Yat-sen''s \"Three Principles of the People\": Nationalism, Democracy, People''s Livelihood - May Fourth Movement (1919): Protest against Paris Peace Conference (Versailles) provisions → rise of modern Chinese nationalism Contrast: Japan industrialised independently and became a colonial power; China struggled against both Western imperialism and internal weakness, eventually undergoing revolution (1911 and 1949). --- AHSEC HS 1st Year History – Paths to Modernisation (Theme 11, NCERT Class 11 Themes in World History).","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bf0' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'nationalism-in-east-asia' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bed-en-238","language":"English","title":"Feudalism in Europe","topic_slug":"feudalism-in-europe","definition":"Feudalism was the social, economic, and political system that dominated Western Europe from about the 9th to 15th centuries. It arose after the collapse of the Carolingian Empire. Origins: Raids by Vikings, Magyars, and Saracens in the 9th-10th centuries forced local populations to seek protection from powerful lords → decentralised authority. Key features: - Hierarchy of lords and vassals - Land grants (fiefs) in exchange for military service - Manorial (serfdom-based) agricultural economy - Church as a unifying institution","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bed' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'feudalism-in-europe' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bed-en-239","language":"English","title":"The Three Orders of Society","topic_slug":"the-three-orders-of-society","definition":"Medieval European society was ideally conceived as three complementary orders: 1. Those who pray (oratores): Clergy — monks, priests, bishops; responsible for spiritual welfare 2. Those who fight (bellatores): Knights and nobles; responsible for military protection 3. Those who work (laboratores): Peasants/serfs; responsible for agricultural production Reality: This was an idealised scheme; in practice, nobles also controlled land and exploited peasants; clergy owned vast estates; merchants (a fourth group) grew in importance by the 12th-13th century.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bed' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'the-three-orders-of-society' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bed-en-240","language":"English","title":"Serfdom and Manor System","topic_slug":"serfdom-and-manor-system","definition":"The Manor was the basic economic unit of feudal Europe — a lord''s estate, typically including: - The lord''s residence (manor house or castle) - Peasant villages - Common land (forests, pastures) - Parish church Serfs: The majority of the rural population. They were bound to the land (cannot leave without lord''s permission), obliged to provide: - Labour service: Working on lord''s land several days per week - Dues: Portion of harvest as rent - Fees: Payment for use of lord''s mill, oven, and other facilities Serfs were not slaves: They had customary rights — strips of land, access to commons, could not be killed arbitrarily.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bed' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'serfdom-and-manor-system' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bed-en-241","language":"English","title":"The Church in Feudal Society","topic_slug":"the-church-in-feudal-society","definition":"The Catholic Church was the most powerful institution in medieval Europe: - Universal authority: Pope claimed supremacy over all Christian kings - Land ownership: Church owned up to 1/3 of agricultural land in some regions - Education: Monasteries and cathedral schools were centres of learning - Social welfare: Ran hospitals, orphanages, and poorhouses - Cultural unifier: Latin as the common language of scholarship and worship Key events: - Investiture Controversy (1076-1122): Struggle between Pope and Holy Roman Emperor over appointment of church officials → Pope Gregory VII vs. Emperor Henry IV → Pope''s victory established Church supremacy - Crusades (1095-1291): Military expeditions to recapture Holy Land; mixed results; increased trade with Middle East","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bed' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'the-church-in-feudal-society' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bed-en-242","language":"English","title":"Towns and Trade in Medieval Europe","topic_slug":"towns-and-trade-in-medieval-europe","definition":"From the 10th-11th century, European towns began to grow again after centuries of decline. Causes of urban revival: - Agricultural surplus (from new techniques: three-field system, heavy plough, horse collar) - Long-distance trade (especially Italian city-states with Middle East) - Demand for crafts and specialised goods Craft guilds: Associations of craftspeople (weavers, blacksmiths, bakers) — regulated quality, training (apprentices → journeymen → masters), and prices. Fairs: Important commercial events — Champagne Fairs in France were major European trading events. Italian city-states: Venice, Genoa, Florence became great commercial centres trading with Byzantine Empire and Islamic world.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bed' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'towns-and-trade-in-medieval-europe' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bed-en-243","language":"English","title":"Decline of Feudalism","topic_slug":"decline-of-feudalism","definition":"Causes: 1. Black Death (1347-1353): Killed 30-60% of European population; labour became scarce → serfs could demand better terms → weakened serfdom 2. Peasant revolts: English Peasants'' Revolt (1381), French Jacquerie (1358) challenged feudal hierarchy 3. Hundred Years'' War (1337-1453): Disrupted feudal military organisation; rise of professional armies 4. Growth of towns and commerce: Merchants accumulated wealth independent of land-ownership 5. Rise of centralised monarchies: Kings gradually reduced power of feudal lords Legacy: Feudalism''s decline set the stage for the Renaissance, Reformation, and eventually capitalism. --- AHSEC HS 1st Year History – The Three Orders (Feudalism in Medieval Europe, Theme 6 NCERT Class 11).","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bed' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'decline-of-feudalism' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bea-en-244","language":"English","title":"Rise of Cities","topic_slug":"rise-of-cities","definition":"Cities emerged as a result of surplus agricultural production, specialisation of labour, and the need for administration. The earliest cities appeared around 3500 BCE in Mesopotamia (modern Iraq). Conditions for urbanisation: - Agricultural surplus (food for non-farmers) - Trade and commerce - Administrative needs - Religious centres (temples) - Defence requirements (fortifications)","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bea' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'rise-of-cities' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bea-en-245","language":"English","title":"Mesopotamian Civilisation","topic_slug":"mesopotamian-civilisation","definition":"Mesopotamia (Greek: \"Land between rivers\") was the region between the Tigris and Euphrates rivers. It is considered one of the world''s earliest civilisations. Key cities: Ur, Uruk, Babylon, Nippur, Akkad. Periods: - Sumerian Period (3500-2350 BCE): City-states like Ur and Uruk - Akkadian Empire (2350-2200 BCE): First empire, under Sargon of Akkad - Neo-Sumerian Period (2100-2000 BCE): Ur III dynasty - Babylonian Period (1900-600 BCE): Hammurabi''s Code (1754 BCE) Society: Divided into free citizens, dependent labourers, and slaves. Priests and kings held power.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bea' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'mesopotamian-civilisation' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bea-en-246","language":"English","title":"Urbanisation in Mesopotamia","topic_slug":"urbanisation-in-mesopotamia","definition":"Mesopotamian cities were temple-centred. The Ziggurat (stepped temple-tower) was the architectural and religious heart of the city. Economic basis: Irrigation agriculture (wheat, barley), crafts, trade. Urban features: - Specialised workers (potters, weavers, metalworkers) - Market places - Administrative scribes - Walls and gates","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bea' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'urbanisation-in-mesopotamia' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bea-en-247","language":"English","title":"Development of Writing","topic_slug":"development-of-writing","definition":"Writing developed in Mesopotamia around 3200 BCE as a record-keeping tool for trade and temple administration. Cuneiform script: - Earliest form: pictographic (picture-symbols) - Evolved into cuneiform (wedge-shaped marks on clay tablets) - Made using a reed stylus on wet clay tablets - Tablets were dried/baked for preservation Stages of writing development: 1. Pictographs (3200 BCE): simple pictures of objects 2. Ideographs: pictures representing ideas 3. Phonetic signs: sounds represented by symbols 4. Alphabetic writing (much later in West Asia)","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bea' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'development-of-writing' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bea-en-248","language":"English","title":"Scribes and Literacy","topic_slug":"scribes-and-literacy","definition":"Scribes were trained writing specialists. They were essential for administration, law, commerce, and religious texts. - Scribes trained in schools called edubba (\"tablet houses\") - Curriculum included writing, arithmetic, surveying, music - Only a small elite could read and write Important Mesopotamian texts: - Epic of Gilgamesh: World''s oldest literary work (flood narrative similar to Biblical Noah story) - Hammurabi''s Code: One of earliest written law codes (282 laws engraved on stele) - Temple accounts, land records, commercial contracts","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bea' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'scribes-and-literacy' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bea-en-249","language":"English","title":"Trade and Economy in Mesopotamia","topic_slug":"trade-and-economy-in-mesopotamia","definition":"Mesopotamia lacked timber, metals, and stone — all had to be imported. Trade networks: Extended to Anatolia (Turkey), Iran, the Indus Valley, and Egypt. Exports: Agricultural products (grain, dates), textiles, pottery. Imports: Timber (cedar from Lebanon), copper (from Oman), gold (from Egypt), semi-precious stones. Merchants (tamkārum): Professional traders who operated on behalf of temples and palaces. Silver used as medium of exchange (standard weight: the shekel). --- AHSEC HS 1st Year History – Writing and City Life (Theme 2 based on NCERT Class 11 Themes in World History).","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bea' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'trade-and-economy-in-mesopotamia' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0d84d8e6ddb2deb7d07-en-250","language":"English","title":"Vector and Scalar Foundations, Invariance, and Algebraic Rules","topic_slug":"vector-and-scalar-foundations-invariance-and-algebraic-rules","definition":"Physical quantities in two or three dimensions are classified based on their transformation properties under spatial coordinate rotations and their adherence to vector addition laws. PHYSICAL QUANTITIES +------------------------+------------------------+ SCALARS VECTORS Specified entirely by a single Possess magnitude AND direction; numerical magnitude with unit; MUST obey Triangle / Parallelogram invariant under axis rotation. laws of vector addition. Classification Criteria and Definitive Properties Scalar Quantities: Completely described by a numerical magnitude and algebraic sign. They obey the rules of ordinary algebra. Examples include volume, mass, speed, density, number of moles, angular frequency, temperature, pressure, time, work, power, gravitational potential, coefficient of friction, and electric charge. Electric Current: Possesses magnitude and a directional sense along a conductor, yet is classified as a scalar because currents add algebraically at circuit nodes (I {\\text{net}} = I 1 + I 2) according to charge conservation, rather than by vector addition laws.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0d84d8e6ddb2deb7d07' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'vector-and-scalar-foundations-invariance-and-algebraic-rules' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0d84d8e6ddb2deb7d07-en-251","language":"English","title":"Vector Addition Laws, Analytical Trigonometry, and Relative Planar Motion","topic_slug":"vector-addition-laws-analytical-trigonometry-and-relative-planar-motion","definition":"VECTOR ADDITION METHODS +-------------------------+-------------------------+ GRAPHICAL LAWS ANALYTICAL FORMULATION Head-to-Tail Triangle Law Law of Cosines (Magnitude) Parallelogram Law Law of Sines (Direction) Triangle and Parallelogram Laws of Vector Addition Triangle Law (Head-to-Tail Method): If two vectors \\vec{A} and \\vec{B} are represented in magnitude and direction by two consecutive sides of a triangle taken in order, their resultant \\vec{R} = \\vec{A} + \\vec{B} is represented by the third side directed from the tail of the first to the head of the second. Commutative Law: A + B = B + A. Vector addition is commutative, representing the same diagonal in a parallelogram. Associative Law: (A + B) + C = A + (B + C). Vector addition is associative, allowing grouping without changing the final resultant.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0d84d8e6ddb2deb7d07' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'vector-addition-laws-analytical-trigonometry-and-relative-planar-motion' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0d84d8e6ddb2deb7d07-en-252","language":"English","title":"Resolution of Vectors, Unit Vector Spaces, and 3D Component Mechanics","topic_slug":"resolution-of-vectors-unit-vector-spaces-and-3d-component-mechanics","definition":"VECTOR RESOLUTION +-----------------------+-----------------------+ PLANAR 2D SPACE THREE-DIMENSIONAL SPACE A = Ax·î + Ay·ĵ A = Ax·î + Ay·ĵ + Az·k̂ Ax = A·cos θ, Ay = A·sin θ Ax = A·cos α, Ay = A·cos β, Az = A·cos γ A = √(Ax² + Ay²) A = √(Ax² + Ay² + Az²) Orthogonal Bases and Direction Cosines In three-dimensional Cartesian space, mutually perpendicular unit vectors \\hat{i}, \\hat{j}, \\hat{k} are defined along the positive x, y, z axes respectively: i · i = j · j = k · k = 1; i · j = j · k = k · i = 0. Mutually orthogonal unit vectors satisfy identity and orthogonality conditions. Any vector \\vec{A} can be resolved into unique rectangular components: A = A x i + A y j + A z k.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0d84d8e6ddb2deb7d07' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'resolution-of-vectors-unit-vector-spaces-and-3d-component-mechanics' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0d84d8e6ddb2deb7d07-en-253","language":"English","title":"Planar Kinematics: Parametric Trajectories, Calculus, and Geometric Paths","topic_slug":"planar-kinematics-parametric-trajectories-calculus-and-geometric-paths","definition":"PLANAR KINEMATICS +----------------------+----------------------+ PARAMETRIC POSITION VECTOR VELOCITY & ACCELERATION r(t) = x(t)·î + y(t)·ĵ v(t) = dr/dt = vx·î + vy·ĵ Displacement: Δr = r(t₂) - r(t₁) a(t) = dv/dt = ax·î + ay·ĵ Position, Velocity, and Acceleration Vectors in a Plane Position Vector: Connects the reference origin O to particle position P(x, y) at time t: r(t) = x(t)i + y(t)j. Position is the sum of coordinate functions scaled by unit vectors. Instantaneous Velocity Vector: Directed tangentially along the instantaneous path of the particle: v(t) = dx/dt i + dy/dt j = v x i + v y j. Velocity is the time derivative of the position vector. Instantaneous Acceleration Vector: a(t) = dv/dt = d^2x/dt^2 i + d^2y/dt^2 j = a x i + a y j. Acceleration is the time derivative of the velocity vector.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0d84d8e6ddb2deb7d07' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'planar-kinematics-parametric-trajectories-calculus-and-geometric-paths' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0d84d8e6ddb2deb7d07-en-254","language":"English","title":"Projectile Motion: Parabolic Trajectories, Flight Parameters, and Energetics","topic_slug":"projectile-motion-parabolic-trajectories-flight-parameters-and-energetics","definition":"A projectile is any body in free flight subject solely to uniform downward gravitational acceleration (\\vec{a} = -g\\hat{j}), assuming air resistance is negligible. y Apex (vy = 0, vx = v₀·cos θ₀) . '' '' . . '' '' . . '' '' . v₀ '' '' / \\ θ₀ / \\ 0----+------------------------------------- --- x Origin (y = 0) Range R Orthogonal Kinematic Breakdown Horizontal Axis (x): Zero horizontal acceleration (a x = 0): x(t) = v0 cos θ0 t. Horizontal motion is uniform due to zero acceleration. Vertical Axis (y): Constant downward acceleration (a y = -g): y(t) = v0 sin θ0 t - 0.5 g t^2. Vertical motion is under constant gravitational acceleration. Derivation: Parabolic Trajectory Equation Solve for time t from the horizontal position equation: t = x / (v0 cos θ0). Solving horizontal position for time allows substitution into the vertical component.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0d84d8e6ddb2deb7d07' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'projectile-motion-parabolic-trajectories-flight-parameters-and-energetics' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0d84d8e6ddb2deb7d07-en-255","language":"English","title":"Uniform Circular Motion: Centripetal Kinematics and Dynamics","topic_slug":"uniform-circular-motion-centripetal-kinematics-and-dynamics","definition":"UNIFORM CIRCULAR MOTION (Speed v = const.) +----------------------------+----------------------------+ ANGULAR VARIABLES CENTRIPETAL ACCELERATION ω = dθ/dt ac = v² / R (Directed Inward) v = ω·R ac = ω²·R = 4π²·ν²·R T = 1/ν = 2π/ω Vector changes continuously Uniform circular motion describes motion along a circular path of radius R at constant scalar speed v. While the speed is constant, the velocity vector \\vec{v} continuously changes direction, producing an instantaneous centripetal acceleration directed toward the center of the circle. v'' (Tangent at P'') ^ / P'' / \\ r'' / \\ Δr / Δθ \\ ------- P C r v (Tangent at P) Derivation: Centripetal Acceleration Magnitude and Inward Direction Let a particle move along a circular path of radius R centered at C. Over a time interval \\Delta t, the particle moves from point P (position \\vec{r}, velocity \\vec{v}) to point P'' (position \\vec{r}'', velocity \\vec{v}'').","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0d84d8e6ddb2deb7d07' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'uniform-circular-motion-centripetal-kinematics-and-dynamics' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0d84d8e6ddb2deb7d06-en-256","language":"English","title":"Theorem 1: The Slope of a Velocity-Time (v-t) Graph Equals Acceleration","topic_slug":"theorem-1-the-slope-of-a-velocity-time-v-t-graph-equals-acceleration","definition":"By definition, instantaneous acceleration is the limit of average acceleration over an infinitesimal time step: a = lim {Δt→0} (v(t+Δt) - v(t)) / Δt = dv/dt. On a Cartesian plot with v along the vertical axis and t along the horizontal axis, the quantity \\frac{dv}{dt} corresponds to the geometric slope (\\tan \\phi) of the tangent line to the curve: Since a = dv/dt is the slope of the v-t graph, a horizontal tangent implies zero instantaneous acceleration. - At local peaks or troughs of a v-t curve, the tangent line is horizontal (\\tan \\phi = 0), so a = 0. v B (Peak: a = 0) .---. / \\ D (Peak: a = 0) / \\ .---. / \\ / \\ / \\ / \\ A \\ / (Slope = a) ''---'' C (Trough: a = 0) +--------------------------------------------- t","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0d84d8e6ddb2deb7d06' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'theorem-1-the-slope-of-a-velocity-time-v-t-graph-equals-acceleration' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0d84d8e6ddb2deb7d06-en-257","language":"English","title":"Theorem 2: The Area Under a Velocity-Time (v-t) Curve Equals Displacement","topic_slug":"theorem-2-the-area-under-a-velocity-time-v-t-curve-equals-displacement","definition":"The net spatial displacement over an interval [t i, t f] is given by the integral of velocity: Δx = ∫[t i, t f] v(t) dt. This area summation accounts for the direction via the algebraic sign of v(t). On a v-t plot, the product v(t)\\, dt corresponds to the area of an infinitesimal vertical strip of height v and width dt. Summing these strips across the full interval yields the area bounded between the curve and the time axis: - Dimensional Check: [v][dt] = (L/T) T = L. The area under a v-t graph carries the dimensions of length. - Distance (Path Length): Sum of absolute areas: s = ∫[t i, t f] v(t) dt. By taking the absolute value, all movement contributes positively to the total path length.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0d84d8e6ddb2deb7d06' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'theorem-2-the-area-under-a-velocity-time-v-t-curve-equals-displacement' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0d84d8e6ddb2deb7d06-as-258","language":"Assamese","title":"সুষম ত্বৰণৰ গতি সমীকৰণ","topic_slug":"সুষম-ত্বৰণৰ-গতি-সমীকৰণ","definition":"স্থিৰ ত্বৰণেৰে সৰলৰেখাত গতিশীল বস্তুৰ বাবে তলৰ সমীকৰণকেইটা প্ৰতিষ্ঠা কৰা হয়: 1. v = v₀ + at 2. x = v₀t + (1/2)at² (বা x - x₀ = v₀t + (1/2)at² ) 3. v² = v₀² + 2ax (বা v² = v₀² + 2a(x - x₀) ) 4. n-তম ছেকেণ্ডত অতিক্ৰম কৰা দূৰত্ব: sₙ = v₀ + (a/2)(2n - 1) ---","title_as":"সুষম ত্বৰণৰ গতি সমীকৰণ","topic_slug_as":"সুষম-ত্বৰণৰ-গতি-সমীকৰণ","definition_as":"স্থিৰ ত্বৰণেৰে সৰলৰেখাত গতিশীল বস্তুৰ বাবে তলৰ সমীকৰণকেইটা প্ৰতিষ্ঠা কৰা হয়: 1. v = v₀ + at 2. x = v₀t + (1/2)at² (বা x - x₀ = v₀t + (1/2)at² ) 3. v² = v₀² + 2ax (বা v² = v₀² + 2a(x - x₀) ) 4. n-তম ছেকেণ্ডত অতিক্ৰম কৰা দূৰত্ব: sₙ = v₀ + (a/2)(2n - 1) ---","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0d84d8e6ddb2deb7d06' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'সুষম-ত্বৰণৰ-গতি-সমীকৰণ' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'Assamese');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0d84d8e6ddb2deb7d05-en-259","language":"English","title":"Equation of a simple pendulum","topic_slug":"equation-of-a-simple-pendulum","definition":"Assume the time period depends on length l, acceleration due to gravity g and mass m: T ∝ lᵃ gᵇ mᶜ . Using [T] = [L]ᵃ[L T⁻²]ᵇ[M]ᶜ gives c = 0, a = 1/2 and b = −1/2. Hence T = K √(l/g) , where K is dimensionless. Experiment gives K = 2π, so T = 2π√(l/g) .","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0d84d8e6ddb2deb7d05' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'equation-of-a-simple-pendulum' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0d84d8e6ddb2deb7d05-en-260","language":"English","title":"Stokes’ law and terminal velocity","topic_slug":"stokes-law-and-terminal-velocity","definition":"For a small sphere of radius r and density ρ falling through a fluid of viscosity η and density ρf, the viscous force is Fv = 6πηrv . At terminal speed, effective weight equals viscous drag: (4/3)πr³(ρ − ρf)g = 6πηvₜ . Thus vₜ = [2r²(ρ − ρf)g]/(9η) .","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0d84d8e6ddb2deb7d05' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'stokes-law-and-terminal-velocity' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0d84d8e6ddb2deb7d05-en-261","language":"English","title":"Van der Waals equation","topic_slug":"van-der-waals-equation","definition":"For one mole of a real gas, (P + a/Vm²)(Vm − b) = RT . Here a accounts for intermolecular attraction and b accounts for the finite volume of molecules. Dimensional analysis gives [a] = [P][V]² mol⁻² = M L⁵ T⁻² mol⁻² , [b] = [V] mol⁻¹ = L³ mol⁻¹ , [R] = M L² T⁻² K⁻¹ mol⁻¹ .","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0d84d8e6ddb2deb7d05' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'van-der-waals-equation' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0d84d8e6ddb2deb7d05-en-262","language":"English","title":"Testing equation validity by homogeneity","topic_slug":"testing-equation-validity-by-homogeneity","definition":"For the kinematic equation x = x₀ + v₀t + (1/2)at² , the dimensions of the terms are - [x₀] = [L] - [v₀t] = [L T⁻¹][T] = [L] - [(1/2)at²] = [L T⁻²][T²] = [L] Every additive term is a length, so the equation is dimensionally consistent. Physical quantities with different dimensions cannot be added or subtracted; velocity cannot be added to force, and mass cannot be subtracted from temperature.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0d84d8e6ddb2deb7d05' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'testing-equation-validity-by-homogeneity' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0d84d8e6ddb2deb7d05-en-263","language":"English","title":"Empirical simple-harmonic-motion period derivation","topic_slug":"empirical-simple-harmonic-motion-period-derivation","definition":"Assume the period of a pendulum depends on bob mass m, length l and gravitational acceleration g: T = k mˣ lʸ gᶻ . Using dimensions gives x = 0, z = −1/2 and y = 1/2. Hence T = k √(l/g) . Dimensional analysis leaves k undetermined; experiment or dynamics gives k = 2π , so T = 2π√(l/g) .","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0d84d8e6ddb2deb7d05' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'empirical-simple-harmonic-motion-period-derivation' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0d84d8e6ddb2deb7d05-en-264","language":"English","title":"Hydrodynamic drag law — Stokes’ law derivation","topic_slug":"hydrodynamic-drag-law-stokes-law-derivation","definition":"Assume F ∝ ηᵃ rᵇ vᶜ , where η is dynamic viscosity, r is radius and v is terminal speed. Matching dimensions gives a = 1, b = 1 and c = 1, so F = K η r v . Experiment gives K = 6π, therefore F = 6πηrv .","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0d84d8e6ddb2deb7d05' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'hydrodynamic-drag-law-stokes-law-derivation' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0d84d8e6ddb2deb7d05-en-265","language":"English","title":"Real-gas Van der Waals constants","topic_slug":"real-gas-van-der-waals-constants","definition":"For one mole, (P + a/Vm²)(Vm − b) = RT . Homogeneity requires b to have molar-volume dimensions: [b] = [Vm] = [L³ mol⁻¹] . Since a/Vm² has pressure dimensions, [a] = [P][Vm]² = [M L⁻¹ T⁻²][L⁶ mol⁻²] = [M L⁵ T⁻² mol⁻²] . If molar amount is suppressed in a single-particle convention, the source notation is [a] = [M L⁵ T⁻²] and [b] = [M⁰ L³ T⁰] .","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0d84d8e6ddb2deb7d05' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'real-gas-van-der-waals-constants' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0d84d8e6ddb2deb7d05-en-266","language":"English","title":"Limits and failure modes of dimensional analysis","topic_slug":"limits-and-failure-modes-of-dimensional-analysis","definition":"Dimensional analysis is a consistency test, but it has important limits: - It cannot determine dimensionless multipliers such as 2π or 1/2. - It cannot evaluate arguments of transcendental functions. Arguments of sin θ, cos(ωt), e⁻ᵏᵗ and ln(kx) must themselves be dimensionless. - In mechanics, three base dimensions cannot determine a relation involving more than three mutually independent variables. - It cannot derive additive equations containing distinct terms, such as s = ut + (1/2)at² . - It cannot distinguish quantities sharing dimensions, such as work and torque or frequency and angular velocity.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0d84d8e6ddb2deb7d05' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'limits-and-failure-modes-of-dimensional-analysis' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0d84d8e6ddb2deb7d05-as-267","language":"Assamese","title":"সাৰ্থক সংখ্যা","topic_slug":"সাৰ্থক-সংখ্যা","definition":"প্ৰতিটো জোখ-মাখতেই কিছু অনিশ্চয়তা বা ত্ৰুটি সন্নিৱিষ্ট হৈ থাকে। জোখ-মাখৰ ফলাফল এনেদৰে প্ৰকাশ কৰা উচিত যাতে ই জোখৰ শুদ্ধতাৰ সীমা নিৰ্দিষ্ট কৰে। জোখ এটাৰ ফলাফলত বিশ্বাসযোগ্যভাৱে জনা সকলোবোৰ নিশ্চিত অংকৰ সৈতে প্ৰথম অনিশ্চিত অংকটোক একেলগে সাৰ্থক অংক বা সাৰ্থক সংখ্যা (significant figures) বোলে। উদাহৰণস্বৰূপে, $1.62\\text{ s}$-ত $1$ আৰু $6$ নিশ্চিত, $2$ অনিশ্চিত; গতিকে ইয়াত সাৰ্থক সংখ্যা তিনিটা।","title_as":"সাৰ্থক সংখ্যা","topic_slug_as":"সাৰ্থক-সংখ্যা","definition_as":"প্ৰতিটো জোখ-মাখতেই কিছু অনিশ্চয়তা বা ত্ৰুটি সন্নিৱিষ্ট হৈ থাকে। জোখ-মাখৰ ফলাফল এনেদৰে প্ৰকাশ কৰা উচিত যাতে ই জোখৰ শুদ্ধতাৰ সীমা নিৰ্দিষ্ট কৰে। জোখ এটাৰ ফলাফলত বিশ্বাসযোগ্যভাৱে জনা সকলোবোৰ নিশ্চিত অংকৰ সৈতে প্ৰথম অনিশ্চিত অংকটোক একেলগে সাৰ্থক অংক বা সাৰ্থক সংখ্যা (significant figures) বোলে। উদাহৰণস্বৰূপে, $1.62\\text{ s}$-ত $1$ আৰু $6$ নিশ্চিত, $2$ অনিশ্চিত; গতিকে ইয়াত সাৰ্থক সংখ্যা তিনিটা।","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0d84d8e6ddb2deb7d05' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'সাৰ্থক-সংখ্যা' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'Assamese');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0d84d8e6ddb2deb7d05-as-268","language":"Assamese","title":"সাৰ্থক সংখ্যা নিৰ্ধাৰণৰ নিয়মসমূহ","topic_slug":"সাৰ্থক-সংখ্যা-নিৰ্ধাৰণৰ-নিয়মসমূহ","definition":"সকলোবোৰ অশূন্য অংক সাৰ্থক। 2. দুটা অশূন্য অংকৰ মাজত থকা আটাইবোৰ শূন্য সাৰ্থক। 3. সংখ্যাটো $1$-তকৈ সৰু হ''লে দশমিক বিন্দুৰ সোঁফালে আৰু প্ৰথম অশূন্য অংকৰ বাঁওফালে থকা শূন্যবোৰ সাৰ্থক নহয় (যেনে: $0.002308$-ত সাৰ্থক অংক চাৰিটা)। 4. দশমিক বিন্দু নথকা সংখ্যাৰ প্ৰান্তীয় শূন্যবোৰ সাৰ্থক নহয় (যেনে: $123000$-ত তিনিটা সাৰ্থক অংক)। 5. দশমিকযুক্ত সংখ্যাৰ সোঁফালে থকা প্ৰান্তীয় শূন্যবোৰ সাৰ্থক (যেনে: $3.500$-ত চাৰিটা, $0.06900$-ত চাৰিটা)। 6. এককৰ পৰিৱৰ্তনে সাৰ্থক সংখ্যাৰ সলনি নকৰাৰ বাবে বৈজ্ঞানিক সংকেত $a \\times 10^b$ ব্যৱহাৰ কৰা হয়, য''ত $1 \\le a < 10$। ইয়াত $10$-ৰ ঘাত সাৰ্থক অংকৰ হিচাপত নাহে।","title_as":"সাৰ্থক সংখ্যা নিৰ্ধাৰণৰ নিয়মসমূহ","topic_slug_as":"সাৰ্থক-সংখ্যা-নিৰ্ধাৰণৰ-নিয়মসমূহ","definition_as":"সকলোবোৰ অশূন্য অংক সাৰ্থক। 2. দুটা অশূন্য অংকৰ মাজত থকা আটাইবোৰ শূন্য সাৰ্থক। 3. সংখ্যাটো $1$-তকৈ সৰু হ''লে দশমিক বিন্দুৰ সোঁফালে আৰু প্ৰথম অশূন্য অংকৰ বাঁওফালে থকা শূন্যবোৰ সাৰ্থক নহয় (যেনে: $0.002308$-ত সাৰ্থক অংক চাৰিটা)। 4. দশমিক বিন্দু নথকা সংখ্যাৰ প্ৰান্তীয় শূন্যবোৰ সাৰ্থক নহয় (যেনে: $123000$-ত তিনিটা সাৰ্থক অংক)। 5. দশমিকযুক্ত সংখ্যাৰ সোঁফালে থকা প্ৰান্তীয় শূন্যবোৰ সাৰ্থক (যেনে: $3.500$-ত চাৰিটা, $0.06900$-ত চাৰিটা)। 6. এককৰ পৰিৱৰ্তনে সাৰ্থক সংখ্যাৰ সলনি নকৰাৰ বাবে বৈজ্ঞানিক সংকেত $a \\times 10^b$ ব্যৱহাৰ কৰা হয়, য''ত $1 \\le a < 10$। ইয়াত $10$-ৰ ঘাত সাৰ্থক অংকৰ হিচাপত নাহে।","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0d84d8e6ddb2deb7d05' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'সাৰ্থক-সংখ্যা-নিৰ্ধাৰণৰ-নিয়মসমূহ' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'Assamese'