UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0d84d8e6ddb2deb7d05-as-269","language":"Assamese","title":"গণিতীয় প্ৰক্ৰিয়া আৰু গোটকৰণ","topic_slug":"গণিতীয়-প্ৰক্ৰিয়া-আৰু-গোটকৰণ","definition":"পূৰণ বা হৰণ: অন্তিম ফলাফলত মূল ৰাশিসমূহৰ ভিতৰত আটাইতকৈ কম সাৰ্থক অংক থকা সংখ্যাটোৰ সমান সাৰ্থক অংক থাকিব লাগিব। - যোগ বা বিয়োগ: অন্তিম ফলাফলত আটাইতকৈ কম দশমিক স্থান থকা সংখ্যাটোৰ সমান দশমিক স্থানহে থাকিব লাগিব। - গোটকৰণৰ নিয়ম: বাদ দিবলগীয়া অংকটো $5$-তকৈ ডাঙৰ হ''লে আগৰ অংকটোত $1$ যোগ হয়, $5$-তকৈ সৰু হ''লে অপৰিৱৰ্তিত থাকে। বাদ দিবলগীয়া অংকটো $5$ হ''লে তাৰ আগৰটো যুগ্ম থাকিলে অপৰিৱৰ্তিত থাকে, কিন্তু অযুগ্ম হ''লে $1$ বৃদ্ধি পায়।","title_as":"গণিতীয় প্ৰক্ৰিয়া আৰু গোটকৰণ","topic_slug_as":"গণিতীয়-প্ৰক্ৰিয়া-আৰু-গোটকৰণ","definition_as":"পূৰণ বা হৰণ: অন্তিম ফলাফলত মূল ৰাশিসমূহৰ ভিতৰত আটাইতকৈ কম সাৰ্থক অংক থকা সংখ্যাটোৰ সমান সাৰ্থক অংক থাকিব লাগিব। - যোগ বা বিয়োগ: অন্তিম ফলাফলত আটাইতকৈ কম দশমিক স্থান থকা সংখ্যাটোৰ সমান দশমিক স্থানহে থাকিব লাগিব। - গোটকৰণৰ নিয়ম: বাদ দিবলগীয়া অংকটো $5$-তকৈ ডাঙৰ হ''লে আগৰ অংকটোত $1$ যোগ হয়, $5$-তকৈ সৰু হ''লে অপৰিৱৰ্তিত থাকে। বাদ দিবলগীয়া অংকটো $5$ হ''লে তাৰ আগৰটো যুগ্ম থাকিলে অপৰিৱৰ্তিত থাকে, কিন্তু অযুগ্ম হ''লে $1$ বৃদ্ধি পায়।","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0d84d8e6ddb2deb7d05' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'গণিতীয়-প্ৰক্ৰিয়া-আৰু-গোটকৰণ' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'Assamese');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0d84d8e6ddb2deb7d05-as-270","language":"Assamese","title":"ভৌতিক ৰাশিবোৰৰ মাত্ৰা","topic_slug":"ভৌতিক-ৰাশিবোৰৰ-মাত্ৰা","definition":"যিকোনো যৌগিক ভৌতিক ৰাশিক সাতটা মৌলিক ৰাশিৰ উপযুক্ত ঘাতৰ পূৰণফল হিচাপে প্ৰকাশ কৰিব পাৰি। কোনো এটা ভৌতিক ৰাশিক প্ৰকাশ কৰিবলৈ মৌলিক ৰাশিবোৰৰ ওপৰত যিবোৰ ঘাত বা সূচক আৰোপ কৰা হয়, সেইবোৰক ৰাশিটোৰ মাত্ৰা (dimensions) বোলে। দৈৰ্ঘ্যক $[L]$, ভৰক $[M]$, সময়ক $[T]$, বৈদ্যুতিক প্ৰৱাহক $[A]$, তাপগতীয় উষ্ণতাক $[K]$, দীপন প্ৰাবল্যক $[\\text{cd}]$ আৰু পদাৰ্থৰ পৰিমাণক $[\\text{mol}]$ চিহ্নৰে মাত্ৰা বুজোৱা হয়।","title_as":"ভৌতিক ৰাশিবোৰৰ মাত্ৰা","topic_slug_as":"ভৌতিক-ৰাশিবোৰৰ-মাত্ৰা","definition_as":"যিকোনো যৌগিক ভৌতিক ৰাশিক সাতটা মৌলিক ৰাশিৰ উপযুক্ত ঘাতৰ পূৰণফল হিচাপে প্ৰকাশ কৰিব পাৰি। কোনো এটা ভৌতিক ৰাশিক প্ৰকাশ কৰিবলৈ মৌলিক ৰাশিবোৰৰ ওপৰত যিবোৰ ঘাত বা সূচক আৰোপ কৰা হয়, সেইবোৰক ৰাশিটোৰ মাত্ৰা (dimensions) বোলে। দৈৰ্ঘ্যক $[L]$, ভৰক $[M]$, সময়ক $[T]$, বৈদ্যুতিক প্ৰৱাহক $[A]$, তাপগতীয় উষ্ণতাক $[K]$, দীপন প্ৰাবল্যক $[\\text{cd}]$ আৰু পদাৰ্থৰ পৰিমাণক $[\\text{mol}]$ চিহ্নৰে মাত্ৰা বুজোৱা হয়।","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0d84d8e6ddb2deb7d05' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'ভৌতিক-ৰাশিবোৰৰ-মাত্ৰা' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'Assamese');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0d84d8e6ddb2deb7d05-as-271","language":"Assamese","title":"মাত্ৰাৰ সূত্ৰ আৰু মাত্ৰিক সমীকৰণ","topic_slug":"মাত্ৰাৰ-সূত্ৰ-আৰু-মাত্ৰিক-সমীকৰণ","definition":"যি প্ৰকাশৰূপৰ দ্বাৰা কোনো ভৌতিক ৰাশি কোন কোন মৌলিক ৰাশিৰ দ্বাৰা কেনেদৰে গঠিত তাক দেখুওৱা হয়, তাকে ৰাশিটোৰ মাত্ৰিক সূত্ৰ বোলে। - উদাহৰণ: আয়তন $[V] = [M^0 L^3 T^0]$, বেগ $[v] = [M^0 L T^{-1}]$, ত্বৰণ $[a] = [M^0 L T^{-2}]$, বল $[F] = [M L T^{-2}]$। ভৌতিক ৰাশি এটাক তাৰ মাত্ৰিক সূত্ৰৰ সৈতে সমতা স্থাপন কৰি পোৱা সমীকৰণক মাত্ৰিক সমীকৰণ বোলে।","title_as":"মাত্ৰাৰ সূত্ৰ আৰু মাত্ৰিক সমীকৰণ","topic_slug_as":"মাত্ৰাৰ-সূত্ৰ-আৰু-মাত্ৰিক-সমীকৰণ","definition_as":"যি প্ৰকাশৰূপৰ দ্বাৰা কোনো ভৌতিক ৰাশি কোন কোন মৌলিক ৰাশিৰ দ্বাৰা কেনেদৰে গঠিত তাক দেখুওৱা হয়, তাকে ৰাশিটোৰ মাত্ৰিক সূত্ৰ বোলে। - উদাহৰণ: আয়তন $[V] = [M^0 L^3 T^0]$, বেগ $[v] = [M^0 L T^{-1}]$, ত্বৰণ $[a] = [M^0 L T^{-2}]$, বল $[F] = [M L T^{-2}]$। ভৌতিক ৰাশি এটাক তাৰ মাত্ৰিক সূত্ৰৰ সৈতে সমতা স্থাপন কৰি পোৱা সমীকৰণক মাত্ৰিক সমীকৰণ বোলে।","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0d84d8e6ddb2deb7d05' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'মাত্ৰাৰ-সূত্ৰ-আৰু-মাত্ৰিক-সমীকৰণ' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'Assamese');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0d84d8e6ddb2deb7d05-as-272","language":"Assamese","title":"মাত্ৰিক বিশ্লেষণ আৰু ইয়াৰ প্ৰয়োগ","topic_slug":"মাত্ৰিক-বিশ্লেষণ-আৰু-ইয়াৰ-প্ৰয়োগ","definition":"মাত্ৰিক বিশ্লেষণৰ মূল তিনিটা প্ৰয়োগ আছে: 1. সমীকৰণৰ মাত্ৰিক সামঞ্জস্যতা বা শুদ্ধতা পৰীক্ষা: মাত্ৰিক সমসত্ব নীতি (Principle of Homogeneity) অনুসৰি যিকোনো ভৌতিক সমীকৰণৰ দুয়োফালে থকা প্ৰতিটো পদৰ মাত্ৰা সদায় একে হ''ব লাগিব। 2. ভৌতিক ৰাশিসমূহৰ মাজত সম্পৰ্ক স্থাপন: পৰস্পৰ নিৰ্ভৰশীল ৰাশিসমূহৰ মাত্ৰা তুলনা কৰি নতুন সূত্ৰ বা সম্পৰ্ক প্ৰতিষ্ঠা কৰিব পাৰি। 3. এককৰ ব্যৱস্থাৰ মাজত ৰূপান্তৰ: এটা পদ্ধতিৰ এককক মাত্ৰাৰ সহায়ত আন এটা একক ব্যৱস্থালৈ পৰিৱৰ্তন কৰিব পাৰি। ---","title_as":"মাত্ৰিক বিশ্লেষণ আৰু ইয়াৰ প্ৰয়োগ","topic_slug_as":"মাত্ৰিক-বিশ্লেষণ-আৰু-ইয়াৰ-প্ৰয়োগ","definition_as":"মাত্ৰিক বিশ্লেষণৰ মূল তিনিটা প্ৰয়োগ আছে: 1. সমীকৰণৰ মাত্ৰিক সামঞ্জস্যতা বা শুদ্ধতা পৰীক্ষা: মাত্ৰিক সমসত্ব নীতি (Principle of Homogeneity) অনুসৰি যিকোনো ভৌতিক সমীকৰণৰ দুয়োফালে থকা প্ৰতিটো পদৰ মাত্ৰা সদায় একে হ''ব লাগিব। 2. ভৌতিক ৰাশিসমূহৰ মাজত সম্পৰ্ক স্থাপন: পৰস্পৰ নিৰ্ভৰশীল ৰাশিসমূহৰ মাত্ৰা তুলনা কৰি নতুন সূত্ৰ বা সম্পৰ্ক প্ৰতিষ্ঠা কৰিব পাৰি। 3. এককৰ ব্যৱস্থাৰ মাজত ৰূপান্তৰ: এটা পদ্ধতিৰ এককক মাত্ৰাৰ সহায়ত আন এটা একক ব্যৱস্থালৈ পৰিৱৰ্তন কৰিব পাৰি। ---","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0d84d8e6ddb2deb7d05' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'মাত্ৰিক-বিশ্লেষণ-আৰু-ইয়াৰ-প্ৰয়োগ' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'Assamese');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0d94d8e6ddb2deb7d09-en-273","language":"English","title":"Derivation: Conservation of Total Mechanical Energy","topic_slug":"derivation-conservation-of-total-mechanical-energy","definition":"Consider a body undergoing displacement \\Delta x under the action of a conservative force F c(x). From the Work-Energy Theorem: W {net} = \\Delta K = K f - K i. Work-energy relation. From the definition of potential energy: W c = -\\Delta V = V i - V f. Relation between conservative work and potential. Summing the two expressions: K f - K i = V i - V f \\implies K f + V f = K i + V i. The total mechanical energy is conserved. If non-conservative forces (like friction F {\\text{nc}}) also act, mechanical energy is dissipated as heat: E f - E i = W {nc}. Work of non-conservative forces equals energy change.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0d94d8e6ddb2deb7d09' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'derivation-conservation-of-total-mechanical-energy' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be8-en-274","language":"English","title":"What is Citizenship","topic_slug":"what-is-citizenship","definition":"Citizenship is a legal and political status that entitles individuals to rights and imposes duties within a political community (usually a state). Three components: 1. Civil citizenship: Civil rights (equality before law, freedom of speech) 2. Political citizenship: Political rights (vote, hold office) 3. Social citizenship: Social rights (education, healthcare, social security) T.H. Marshall (sociologist) traced the evolution of citizenship through these three stages in modern democracies.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be8' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'what-is-citizenship' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be8-en-275","language":"English","title":"Who is a Citizen","topic_slug":"who-is-a-citizen","definition":"Criteria for citizenship vary by country: By birth (jus soli): Anyone born in the country is a citizen (USA, UK traditionally) By descent (jus sanguinis): Citizenship based on parentage (Germany, Japan) By naturalisation: Foreign nationals can become citizens after meeting requirements (residence period, language test, oath of allegiance) In India (Articles 5-11 and Citizenship Act 1955): - By birth (born in India before 1987: automatic; after 2003: both parents must be citizens) - By descent - By registration or naturalisation","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be8' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'who-is-a-citizen' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be8-en-276","language":"English","title":"Active Citizenship","topic_slug":"active-citizenship","definition":"Active citizenship means participating actively in the political and civic life of the community, beyond just holding formal citizenship. Forms: - Voting in elections - Standing for office - Joining political parties or civil society organisations - Paying taxes - Community service - Informed civic discourse Democratic citizenship requires active participation — democracy cannot function with purely passive citizens.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be8' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'active-citizenship' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be8-en-277","language":"English","title":"Citizenship and Nationality","topic_slug":"citizenship-and-nationality","definition":"Nationality is the legal relationship between a person and a nation-state (often same as citizenship in modern states). Distinction: - A person can have nationality without being a citizen (some rights denied) - Citizens usually have full rights; nationals may have restricted rights - Example: British Overseas Nationals — British nationality but not full citizenship rights Dual citizenship: Some countries allow citizenship in two states simultaneously (USA allows this; India does not — though it has Overseas Citizen of India status).","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be8' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'citizenship-and-nationality' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be8-en-278","language":"English","title":"Global Citizenship","topic_slug":"global-citizenship","definition":"Global citizenship is the idea that individuals have rights and responsibilities that extend beyond national borders, as members of a global community. Basis: - Universal human rights apply to all - Global problems (climate change, terrorism, pandemics) require global cooperation - International organisations (UN, WTO) create global governance Critique: Global citizenship lacks enforcement mechanisms; national citizenship remains primary. Tension between global and national identity. --- AHSEC HS 1st Year Political Science – Citizenship chapter.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be8' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'global-citizenship' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be5-en-279","language":"English","title":"What is Equality","topic_slug":"what-is-equality","definition":"Equality means treating all people as equals, without discrimination based on birth, race, sex, religion, or caste. It is a fundamental political value and a cornerstone of democracy. Two dimensions: 1. Formal equality: Equal treatment under the law (equality before law) 2. Substantive equality: Equal opportunity and outcomes in practice","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be5' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'what-is-equality' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be5-en-280","language":"English","title":"Natural and Social Equality","topic_slug":"natural-and-social-equality","definition":"Natural equality: The idea that all human beings are equal in certain fundamental ways (equal moral worth, equal right to dignity). Natural inequalities (physical differences) exist but should not determine social worth. Social equality: Equality in social standing and relationships. Aims to eliminate social hierarchies based on caste, gender, race, or class.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be5' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'natural-and-social-equality' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be5-en-281","language":"English","title":"Civil Equality","topic_slug":"civil-equality","definition":"Civil equality means equal civil rights for all citizens — equal access to the legal system, equal protection under law, and freedom from arbitrary discrimination. Examples: - Equality before law (Article 14, Indian Constitution) - Right to property - Right to freedom of religion","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be5' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'civil-equality' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be5-en-282","language":"English","title":"Political Equality","topic_slug":"political-equality","definition":"Political equality means equal political rights for all citizens — one person, one vote; equal right to stand for election; equal right to hold office. Universal adult franchise: All adult citizens have the right to vote regardless of wealth, gender, or caste. India adopted this in 1950.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be5' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'political-equality' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be5-en-283","language":"English","title":"Economic Equality","topic_slug":"economic-equality","definition":"Economic equality aims to reduce economic disparities — ensuring basic needs are met for all citizens and that wealth is not concentrated in few hands. Approaches: - Progressive taxation - Social security and welfare programmes - Land reform - Public education and healthcare Note: Perfect economic equality may not be achievable, but reducing extreme inequality is a political goal.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be5' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'economic-equality' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be5-en-284","language":"English","title":"Equality and Discrimination","topic_slug":"equality-and-discrimination","definition":"Discrimination means treating people unfairly based on characteristics like caste, race, sex, religion, or disability. Forms of discrimination: - Direct discrimination (explicit) - Indirect discrimination (neutral rules with discriminatory impact) Affirmative action (Positive discrimination): Deliberate policies to help disadvantaged groups (reservations in India for SC/ST/OBC). Debate: Is treating groups differently to achieve equality itself a violation of formal equality? This is the tension between formal and substantive equality. --- AHSEC HS 1st Year Political Science – Equality chapter.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be5' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'equality-and-discrimination' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be4-en-285","language":"English","title":"What is Freedom","topic_slug":"what-is-freedom","definition":"Freedom means the absence of constraints on individual action and the ability to live in a self-directed manner. It is a fundamental value in political theory. Two key aspects: 1. Negative freedom: Absence of external interference/constraints 2. Positive freedom: Ability and capacity to act (self-realisation)","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be4' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'what-is-freedom' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be4-en-286","language":"English","title":"Negative Liberty","topic_slug":"negative-liberty","definition":"Negative liberty focuses on freedom from interference. It means the absence of external obstacles or coercion that prevent individuals from doing what they want. Key thinker: Isaiah Berlin (\"Two Concepts of Liberty,\" 1958) Features: - Individual has a protected private sphere free from state intervention - State should not interfere in personal choices - Minimum government = maximum individual freedom Example: Freedom from censorship, freedom from arbitrary arrest.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be4' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'negative-liberty' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be4-en-287","language":"English","title":"Positive Liberty","topic_slug":"positive-liberty","definition":"Positive liberty focuses on freedom to — the actual ability to fulfil one''s potential. It requires enabling conditions. Features: - True freedom requires resources and capabilities - The state may need to intervene to give people real choices - Poverty, illiteracy, and discrimination restrict positive freedom Example: Right to education enables positive freedom; welfare state enhances positive liberty.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be4' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'positive-liberty' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be4-en-288","language":"English","title":"Freedom of Expression","topic_slug":"freedom-of-expression","definition":"Freedom of expression is the right to express one''s opinions, ideas, and information without government interference. Includes: - Freedom of speech - Freedom of press - Freedom of assembly and association - Artistic and creative expression Why important: - Essential for democracy (informed citizenry) - Enables political participation - Protects minority opinions - Basis for truth-finding (marketplace of ideas) Reasonable Restrictions: Freedom of expression is not absolute. It can be restricted for: - Public order and security - National security - Protection of reputation (defamation laws) - Decency and morality","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be4' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'freedom-of-expression' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be4-en-289","language":"English","title":"Constraints on Freedom","topic_slug":"constraints-on-freedom","definition":"Some constraints on freedom are necessary for ordered social life. Freedom can be limited to: 1. Protect others'' freedom: Your freedom ends where another''s begins 2. Prevent harm: John Stuart Mill''s Harm Principle (only restrict if causing harm to others) 3. Maintain social order: Some regulation needed for collective life 4. Protect rights: Right to privacy may limit press freedom John Stuart Mill''s On Liberty (1859): The state can only legitimately restrict freedom to prevent harm to others. All other restrictions are illegitimate. --- AHSEC HS 1st Year Political Science – Freedom chapter.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be4' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'constraints-on-freedom' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be9-en-290","language":"English","title":"What is Federalism?","topic_slug":"what-is-federalism","definition":"Federalism is an institutional mechanism to accommodate two sets of polities—one at the regional level and the other at the national level. Each government is autonomous in its own sphere. In some federal countries, there is even a system of dual citizenship.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'what-is-federalism' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be9-en-291","language":"English","title":"Federalism in West Indies","topic_slug":"federalism-in-west-indies","definition":"The West Indies is a federation of independent islands. It has a weak central government and the economy of each unit faces a division of the country. The political competition among the units led to the formal dissolution of the federation in 1962.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'federalism-in-west-indies' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be9-en-292","language":"English","title":"Key Features of Federalism","topic_slug":"key-features-of-federalism","definition":"Federalism is an institutional mechanism to accommodate two sets of polities—one at the regional level and the other at the national level. Each government is autonomous in its own sphere. The people have two sets of identities and loyalties—they belong to the region as well as the nation.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'key-features-of-federalism' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be9-en-293","language":"English","title":"Division of Powers","topic_slug":"division-of-powers","definition":"The Indian Constitution has created two sets of government: one for the entire nation called the union government (central government) and one for each unit or State called the State government. Both of these have a constitutional status and clearly identified area of activity. The Constitution clearly demarcates subjects, which are under the exclusive domain of the Union and those under the States.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'division-of-powers' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be9-en-294","language":"English","title":"Union List and Concurrent List","topic_slug":"union-list-and-concurrent-list","definition":"The Union List includes subjects like Defence, Atomic Energy, Foreign Affairs, and Railways. The Concurrent List includes subjects like Education, Trade, and Currency. The Union Legislature alone can make laws on these matters, while the State Legislature alone can make laws on these matters.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'union-list-and-concurrent-list' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be9-en-295","language":"English","title":"Federalism with a Strong Central Government","topic_slug":"federalism-with-a-strong-central-government","definition":"The Indian Constitution has created a strong central government. The framers of the Constitution believed that a strong centre was necessary to stem disintegration and bring about social and political change. The centre has powers to integrate the princely states and to create new States.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'federalism-with-a-strong-central-government' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be9-en-296","language":"English","title":"Importance of Federalism","topic_slug":"importance-of-federalism","definition":"Federalism is essential for a country like India, which has immense diversities and social problems. It helps to accommodate the diversity of the country and to maintain unity. The federal structure of governance adopted by India has been instrumental in maintaining unity and stability.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'importance-of-federalism' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be9-en-297","language":"English","title":"Challenges to Federalism","topic_slug":"challenges-to-federalism","definition":"Federalism can fail if the regions and various communities do not trust each other. The example of Nigeria is instructive, where the federal arrangement failed to produce unity due to the lack of trust among the regions and communities. The Nigerian federation is an example of overlap of religious, ethnic, and economic differences among the units.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'challenges-to-federalism' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be3-en-298","language":"English","title":"Why Do We Need a Constitution?","topic_slug":"why-do-we-need-a-constitution","definition":"A constitution is a set of basic rules that allow for minimal coordination amongst members of a society. These rules must be publicly promulgated and known to all members of the group to achieve a minimal degree of coordination. The rules must also be enforceable, giving citizens assurance that others will follow them, and providing a punishment for those who do not.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be3' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'why-do-we-need-a-constitution' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be3-en-299","language":"English","title":"What Are the Basic Rules of a Constitution?","topic_slug":"what-are-the-basic-rules-of-a-constitution","definition":"The first function of a constitution is to provide a set of basic rules that allow for minimal coordination amongst members of a society. These rules specify who gets to decide what the laws governing the society should be. The constitution decides who has the authority to enact laws and constitutes government in the first place.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be3' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'what-are-the-basic-rules-of-a-constitution' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be3-en-300","language":"English","title":"Limitations on Government Power","topic_slug":"limitations-on-government-power","definition":"The third function of a constitution is to set some limits on what a government can impose on its citizens. These limits are fundamental in the sense that government may never trespass them. Constitutions limit the power of government in many ways, including specifying certain fundamental rights that all citizens possess.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be3' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'limitations-on-government-power' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be3-en-301","language":"English","title":"Fundamental Rights and Liberties","topic_slug":"fundamental-rights-and-liberties","definition":"Citizens will be protected from being arrested arbitrarily and for no reason. Citizens will normally have the right to some basic liberties: to freedom of speech, freedom of conscience, freedom of association, and freedom to conduct a trade or business. In practice, these rights can be limited during times of national emergency, and the constitution specifies the circumstances under which these rights may be withdrawn.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be3' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'fundamental-rights-and-liberties' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be3-en-302","language":"English","title":"Enabling Provisions of a Constitution","topic_slug":"enabling-provisions-of-a-constitution","definition":"Many twentieth-century constitutions, including the Indian Constitution, provide an enabling framework for the government to do certain positive things. The government is empowered to take measures to overcome forms of inequality or deprivation. For example, the Indian Constitution enables the government to take positive welfare measures, such as providing education and healthcare.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be3' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'enabling-provisions-of-a-constitution' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be3-en-303","language":"English","title":"Aspirations and Goals of a Society","topic_slug":"aspirations-and-goals-of-a-society","definition":"Societies with deep entrenched inequalities of various kinds will not only have to set limits on the power of government but also enable and empower the government to take positive measures to overcome these inequalities. The Indian Constitution, for example, aspires to be a society that is free of caste discrimination. The government is empowered to take all necessary steps to achieve this goal.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be3' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'aspirations-and-goals-of-a-society' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be3-en-304","language":"English","title":"Fundamental Identity of a People","topic_slug":"fundamental-identity-of-a-people","definition":"A constitution expresses the fundamental identity of a people. This means the people as a collective entity come into being only through the basic constitution. Constitutional norms are the overarching framework within which one pursues individual aspirations, goals, and freedoms.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be3' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'fundamental-identity-of-a-people' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be7-en-305","language":"English","title":"What are Rights","topic_slug":"what-are-rights","definition":"Rights are claims that individuals make on society and on the state. They define the space within which individuals can act freely and without interference. Characteristics of rights: 1. Rights are claims, not mere freedoms 2. Rights imply corresponding duties 3. Rights are social — they exist within a community 4. Rights are recognised and enforced by law (legal rights) or by moral consensus","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be7' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'what-are-rights' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be7-en-306","language":"English","title":"Why do We Need Rights","topic_slug":"why-do-we-need-rights","definition":"Essential for human dignity: Rights protect individuals from exploitation and oppression 2. Enable development: Rights allow people to develop their capacities 3. Foundation of democracy: Political rights enable participation in governance 4. Prevent tyranny: Rights constrain government power 5. Social harmony: Rights-based order reduces conflict","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be7' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'why-do-we-need-rights' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be7-en-307","language":"English","title":"Legal Rights and the State","topic_slug":"legal-rights-and-the-state","definition":"Legal rights are rights granted by the state through legislation. They are enforceable in courts. Types: - Civil Rights: Freedom of movement, right to property, right to contract - Political Rights: Right to vote, right to stand for election - Social Rights: Right to education, healthcare, social security The state both grants and protects legal rights. Without state recognition and enforcement, rights remain mere moral claims.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be7' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'legal-rights-and-the-state' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be7-en-308","language":"English","title":"Natural Rights","topic_slug":"natural-rights","definition":"Natural rights are rights that all human beings possess by virtue of their human nature — not granted by any government. They are universal, inalienable, and pre-political. Key thinkers: - John Locke: Natural rights are life, liberty, and property - Thomas Jefferson (American Declaration of Independence): \"Life, liberty and the pursuit of happiness\" Critique: Natural rights are difficult to define and may reflect particular cultural values.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be7' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'natural-rights' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be7-en-309","language":"English","title":"Human Rights","topic_slug":"human-rights","definition":"Human rights are rights that belong to every person regardless of nationality, race, sex, or religion. They are universal, inalienable, and indivisible. Universal Declaration of Human Rights (UDHR, 1948): Adopted by the UN General Assembly after WWII. Lists fundamental rights including: - Right to life, liberty, and security - Freedom from torture - Right to education - Right to freedom of thought International Covenants: - International Covenant on Civil and Political Rights (ICCPR) - International Covenant on Economic, Social and Cultural Rights (ICESCR)","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be7' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'human-rights' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be7-en-310","language":"English","title":"Rights in the Indian Constitution","topic_slug":"rights-in-the-indian-constitution","definition":"The Indian Constitution (Part III, Articles 12-35) guarantees Fundamental Rights: 1. Right to Equality (Articles 14-18): Equality before law, prohibition of discrimination 2. Right to Freedom (Articles 19-22): Speech, assembly, movement, profession, life and liberty 3. Right Against Exploitation (Articles 23-24): Prohibition of forced labour, child labour 4. Right to Freedom of Religion (Articles 25-28) 5. Cultural and Educational Rights (Articles 29-30) 6. Right to Constitutional Remedies (Article 32): Right to approach Supreme Court (Dr. Ambedkar called this \"heart and soul\" of the Constitution) --- AHSEC HS 1st Year Political Science – Rights chapter.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be7' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'rights-in-the-indian-constitution' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be6-en-311","language":"English","title":"Social Justice","topic_slug":"social-justice","definition":"Social justice is a concept that refers to the fair distribution of resources, opportunities, and privileges within a society. It aims to address the inequalities and injustices that exist in society, ensuring that everyone has equal access to resources and opportunities. The concept of social justice is closely related to the idea of human rights, which emphasizes the inherent dignity and worth of every individual. Social justice seeks to promote the well-being and dignity of all individuals, particularly those who are marginalized or oppressed. Social justice is a fundamental principle of democracy, as it ensures that power is distributed fairly and that the rights of all citizens are protected.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be6' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'social-justice' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be6-en-312","language":"English","title":"Types of Social Injustice","topic_slug":"types-of-social-injustice","definition":"Social injustice can take many forms, including economic inequality, racial and ethnic discrimination, sexism, and ageism. It can also manifest in the form of unequal access to education, healthcare, and other essential services. Economic inequality is a significant form of social injustice, as it creates a system where some individuals have more power and resources than others. This can lead to a concentration of wealth and power, perpetuating social and economic inequalities. Racial and ethnic discrimination is another form of social injustice, as it denies individuals of certain racial or ethnic backgrounds equal access to opportunities and resources.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be6' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'types-of-social-injustice' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be6-en-313","language":"English","title":"Mechanisms for Social Justice","topic_slug":"mechanisms-for-social-justice","definition":"Social justice can be achieved through various mechanisms, including laws, policies, and social movements. Laws and policies can be enacted to protect the rights of marginalized groups and promote equality. Social movements, such as civil rights movements and feminist movements, have played a crucial role in promoting social justice and challenging unjust systems. Education and awareness-raising are also essential mechanisms for social justice, as they help to raise awareness about the issues and promote empathy and understanding.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be6' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'mechanisms-for-social-justice' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be6-en-314","language":"English","title":"Role of the State in Social Justice","topic_slug":"role-of-the-state-in-social-justice","definition":"The state has a crucial role to play in promoting social justice, as it has the power to enact laws and policies that protect the rights of marginalized groups. The state can also provide essential services, such as education and healthcare, to promote social justice and equality. However, the state can also perpetuate social injustice through its policies and actions, particularly if it is controlled by a dominant group or class.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be6' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'role-of-the-state-in-social-justice' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be6-en-315","language":"English","title":"Challenges to Social Justice","topic_slug":"challenges-to-social-justice","definition":"Social justice is often challenged by powerful interests, such as corporations and wealthy individuals, who may resist changes to the status quo. Social justice is also challenged by systemic barriers, such as racism and sexism, which can perpetuate inequality and injustice. Finally, social justice is challenged by the complexity of social issues, which can make it difficult to identify and address the root causes of social injustice.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be6' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'challenges-to-social-justice' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3e1-en-316","language":"English","title":"Biotechnology and its Applications","topic_slug":"biotechnology-and-its-applications","definition":"Biotechnology is the application of biological principles to develop new products, technologies, and medical treatments. It involves the use of living organisms or their components to create new products or to modify existing ones. Biotechnology has numerous applications in medicine, agriculture, and industry.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3e1' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'biotechnology-and-its-applications' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3e1-en-317","language":"English","title":"Pest Resistant Plants","topic_slug":"pest-resistant-plants","definition":"Pest-resistant plants are genetically engineered to produce toxins that kill specific pests. The toxin is produced by the bacterium Bacillus thuringiensis (Bt) and is incorporated into the plant''s genome. The Bt toxin is coded by a gene named cry, and there are several types of cry genes that control different pests.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3e1' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'pest-resistant-plants' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3e1-en-318","language":"English","title":"Genetically Engineered Insulin","topic_slug":"genetically-engineered-insulin","definition":"Insulin is a hormone produced by the pancreas that regulates blood sugar levels. Diabetic patients require insulin therapy to control their blood sugar levels. Genetically engineered insulin is produced through recombinant DNA technology, where the human insulin gene is inserted into a bacterium, such as E. coli.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3e1' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'genetically-engineered-insulin' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3e1-en-319","language":"English","title":"Gene Therapy","topic_slug":"gene-therapy","definition":"Gene therapy is a medical treatment that involves the introduction of healthy copies of a gene into a patient''s cells to replace faulty or missing genes. Gene therapy is used to treat genetic disorders, such as adenosine deaminase (ADA) deficiency. The first clinical gene therapy was performed in 1990 on a 4-year-old girl with ADA deficiency.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3e1' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'gene-therapy' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3e1-en-320","language":"English","title":"Molecular Diagnosis","topic_slug":"molecular-diagnosis","definition":"Molecular diagnosis involves the use of recombinant DNA technology, Polymerase Chain Reaction (PCR), and Enzyme Linked Immuno-sorbent Assay (ELISA) to detect genetic disorders. PCR is a technique that amplifies specific DNA sequences, allowing for the detection of very low concentrations of DNA. ELISA is a technique that detects the presence of antigens or antibodies in a sample.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3e1' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'molecular-diagnosis' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3e1-en-321","language":"English","title":"Transgenic Animals","topic_slug":"transgenic-animals","definition":"Transgenic animals are animals that have had their DNA manipulated to possess and express an extra (foreign) gene. Transgenic animals are used to study normal physiology and development, to study disease, to produce biological products, and to test vaccine safety and chemical safety.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3e1' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'transgenic-animals' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3e1-en-322","language":"English","title":"Biological Products","topic_slug":"biological-products","definition":"Biological products, such as human proteins, can be produced in transgenic animals. These products can be used to treat human diseases, such as emphysema and cystic fibrosis. Transgenic animals can also be used to produce vaccines and to test the safety of vaccines.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3e1' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'biological-products' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3e1-en-323","language":"English","title":"Vaccine Safety and Chemical Safety Testing","topic_slug":"vaccine-safety-and-chemical-safety-testing","definition":"Transgenic animals are being developed to test the safety of vaccines and chemicals. These animals are made to be more sensitive to toxic substances, allowing for the detection of toxicity in less time. Transgenic animals can also be used to test the safety of new medicines.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3e1' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'vaccine-safety-and-chemical-safety-testing' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3e1-en-324","language":"English","title":"Ethical Issues","topic_slug":"ethical-issues","definition":"The manipulation of living organisms by the human race raises ethical concerns. The Indian Government has set up organizations, such as GEAC, to regulate the use of genetically modified organisms. The modification and usage of living organisms for public services has also created problems with patents granted for the same.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3e1' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'ethical-issues' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3e0-en-325","language":"English","title":"Biotechnology: Principles and Processes","topic_slug":"biotechnology-principles-and-processes","definition":"Biotechnology is the application of biological principles to develop new products, technologies, and processes to improve human life and the environment. It involves the use of living organisms, cells, or biological molecules to develop new products, technologies, and processes. Biotechnology has revolutionized various fields, including medicine, agriculture, and industry.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3e0' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'biotechnology-principles-and-processes' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3e0-en-326","language":"English","title":"Tools of Recombinant DNA Technology","topic_slug":"tools-of-recombinant-dna-technology","definition":"Genetic engineering or recombinant DNA technology can be accomplished only if we have the key tools, i.e., restriction enzymes, polymerase enzymes, ligases, vectors, and the host organism. Restriction enzymes, polymerase enzymes, ligases, vectors, and the host organism are the essential tools for recombinant DNA technology. These tools enable the manipulation of DNA molecules, allowing for the creation of new combinations of genetic material.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3e0' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'tools-of-recombinant-dna-technology' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3e0-en-327","language":"English","title":"Restriction Enzymes","topic_slug":"restriction-enzymes","definition":"Restriction enzymes are enzymes that cut DNA molecules at specific recognition sequences. They are also known as restriction endonucleases. Restriction enzymes are used in genetic engineering to form ''recombinant'' molecules of DNA, which are composed of DNA from different sources/genomes.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3e0' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'restriction-enzymes' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3e0-en-328","language":"English","title":"Palindromic Nucleotide Sequences","topic_slug":"palindromic-nucleotide-sequences","definition":"Palindromic nucleotide sequences are sequences of base pairs that read the same on the two strands when orientation of reading is kept the same. Restriction enzymes cut the strand of DNA a little away from the centre of the palindrome sites, but between the same two bases on the opposite strands. This leaves single-stranded portions at the ends, which are known as sticky ends.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3e0' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'palindromic-nucleotide-sequences' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3e0-en-329","language":"English","title":"Separation and Isolation of DNA Fragments","topic_slug":"separation-and-isolation-of-dna-fragments","definition":"The cutting of DNA by restriction endonucleases results in the fragmentation of DNA. These fragments can be separated by a technique known as gel electrophoresis. DNA fragments are negatively charged molecules that can be separated by forcing them to move towards the anode under an electric field through a medium/matrix.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3e0' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'separation-and-isolation-of-dna-fragments' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3e0-en-330","language":"English","title":"Cloning Vectors","topic_slug":"cloning-vectors","definition":"Cloning vectors are plasmids or bacteriophages that have the ability to replicate within bacterial cells independent of the control of chromosomal DNA. Vectors used at present are engineered in such a way that they help easy linking of foreign DNA and selection of recombinants from non-recombinants. The features required to facilitate cloning into a vector include origin of replication, selectable marker, and cloning sites.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3e0' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'cloning-vectors' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3e0-en-331","language":"English","title":"Origin of Replication","topic_slug":"origin-of-replication","definition":"Origin of replication (ori) is a sequence from where replication starts and any piece of DNA when linked to this sequence can be made to replicate within the host cells. This sequence is also responsible for controlling the copy number of the linked DNA. So, if one wants to recover many copies of the target DNA, it should be cloned in a vector whose origin supports high copy number.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3e0' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'origin-of-replication' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3e0-en-332","language":"English","title":"Selectable Marker","topic_slug":"selectable-marker","definition":"Selectable marker is a gene that helps in identifying and eliminating non-transformants and selectively permitting the growth of the transformants. Genes encoding resistance to antibiotics such as ampicillin, chloramphenicol, tetracycline, or kanamycin, etc., are considered useful selectable markers for E. coli. The normal E. coli cells do not carry resistance against any of these antibiotics.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3e0' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'selectable-marker' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3e0-en-333","language":"English","title":"Cloning Sites","topic_slug":"cloning-sites","definition":"Cloning sites are the recognition sites for the commonly used restriction enzymes. Presence of more than one recognition site within the vector will generate several fragments, which will complicate the gene cloning. The ligation of alien DNA is carried out at a restriction site present in one of the two antibiotic resistance genes.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3e0' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'cloning-sites' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3e0-en-334","language":"English","title":"Vectors for Cloning Genes in Plants and Animals","topic_slug":"vectors-for-cloning-genes-in-plants-and-animals","definition":"Vectors for cloning genes in plants and animals are derived from bacteria and viruses that have known this for ages – how to deliver genes to transform eukaryotic cells and force them to do what the bacteria or viruses want. For example, Agrobacterium tumefaciens, a pathogen of several dicot plants, is able to deliver a piece of DNA known as ''T-DNA'' to transform normal plant cells into a tumor and direct these tumor cells to produce the chemicals required by the pathogen. Similarly, retroviruses in animals have the ability to transform normal cells into cancerous cells.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3e0' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'vectors-for-cloning-genes-in-plants-and-animals' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3dc-en-335","language":"English","title":"Evolution and Genetic Material","topic_slug":"evolution-and-genetic-material","definition":"The genetic material is the molecule that carries and transmits genetic information from one generation to the next. The discovery of the genetic material was a long process that involved the contributions of many scientists, including Gregor Mendel, Walter Sutton, Thomas Hunt Morgan, and others. The genetic material was initially thought to be a protein, but it was later discovered to be DNA.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3dc' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'evolution-and-genetic-material' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3dc-en-336","language":"English","title":"Packaging of DNA Helix","topic_slug":"packaging-of-dna-helix","definition":"The DNA double helix is a long molecule that is approximately 2.2 meters in length in a typical mammalian cell. This length is far greater than the dimension of a typical nucleus, which is approximately 10-6 m. To package the DNA helix, it is wrapped around positively charged histone proteins to form a structure called a nucleosome. A typical nucleosome contains 200 bp of DNA helix and is the repeating unit of a structure in the nucleus called chromatin.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3dc' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'packaging-of-dna-helix' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3dc-en-337","language":"English","title":"Chromatin Structure","topic_slug":"chromatin-structure","definition":"Chromatin is a thread-like stained (coloured) body seen in the nucleus. The nucleosomes in chromatin are seen as ''beads-on-string'' structure when viewed under an electron microscope. The beads-on-string structure in chromatin is packaged to form chromatin fibers that are further coiled and condensed at the metaphase stage of cell division to form chromosomes. The packaging of chromatin at higher levels requires additional sets of proteins that collectively are referred to as Non-histone Chromosomal (NHC) proteins.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3dc' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'chromatin-structure' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3dc-en-338","language":"English","title":"The Search for Genetic Material","topic_slug":"the-search-for-genetic-material","definition":"The discovery of nuclein by Meischer and the principles of inheritance by Mendel were almost simultaneous, but it took a long time to discover and prove that DNA acts as a genetic material. By 1926, the quest to determine the mechanism for genetic inheritance had reached the molecular level. Previous discoveries had narrowed the search to the chromosomes located in the nucleus of most cells, but the question of what molecule was actually the genetic material had not been answered.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3dc' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'the-search-for-genetic-material' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3dc-en-339","language":"English","title":"Transforming Principle","topic_slug":"transforming-principle","definition":"Frederick Griffith, in a series of experiments with Streptococcus pneumoniae (bacterium responsible for pneumonia), witnessed a miraculous transformation in the bacteria. When Griffith injected a mixture of heat-killed S and live R bacteria into mice, the mice died, and living S bacteria were recovered from the dead mice. He concluded that the R strain bacteria had somehow been transformed by the heat-killed S strain bacteria, and that some ''transforming principle'' had been transferred from the heat-killed S strain to the R strain.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3dc' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'transforming-principle' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3dc-en-340","language":"English","title":"Biochemical Characterisation of Transforming Principle","topic_slug":"biochemical-characterisation-of-transforming-principle","definition":"Prior to the work of Oswald Avery, Colin MacLeod, and Maclyn McCarty, the genetic material was thought to be a protein. They worked to determine the biochemical nature of the ''transforming principle'' in Griffith''s experiment and discovered that DNA alone from S bacteria caused R bacteria to become transformed. They also discovered that protein-digesting enzymes (proteases) and RNA-digesting enzymes (RNases) did not affect transformation, suggesting that the transforming substance was not a protein or RNA.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3dc' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'biochemical-characterisation-of-transforming-principle' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3dc-en-341","language":"English","title":"The Genetic Material is DNA","topic_slug":"the-genetic-material-is-dna","definition":"The unequivocal proof that DNA is the genetic material came from the experiments of Alfred Hershey and Martha Chase (1952). They worked with viruses that infect bacteria called bacteriophages and discovered that DNA is the material that passes from the virus to the bacteria. They grew some viruses on a medium that contained radioactive phosphorus and some others on medium that contained radioactive sulfur. Viruses grown in the presence of radioactive phosphorus contained radioactive DNA but not radioactive protein, while viruses grown on radioactive sulfur contained radioactive protein but not radioactive DNA.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3dc' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'the-genetic-material-is-dna' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3dc-en-342","language":"English","title":"Properties of Genetic Material","topic_slug":"properties-of-genetic-material","definition":"DNA is the predominant genetic material, whereas RNA performs dynamic functions of messenger and adapter. A molecule that can act as a genetic material must fulfill the following criteria: it should be able to generate its replica (replication), it should be chemically and structurally stable, it should provide the scope for slow changes (mutation) that are required for evolution, and it should be able to express itself in the form of ''Mendelian Characters''. Both DNA and RNA have the ability to direct their duplications due to the rule of base pairing and complementarity. DNA is chemically less reactive and structurally more stable than RNA due to the presence of thymine at the place of uracil.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3dc' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'properties-of-genetic-material' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3dc-en-343","language":"English","title":"RNA World","topic_slug":"rna-world","definition":"RNA was the first genetic material. There is now enough evidence to suggest that essential life processes (such as metabolism, translation, splicing, etc.) evolved around RNA. RNA used to act as a genetic material as well as a catalyst, and it is now known to be catalytic and reactive.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3dc' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'rna-world' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3dd-en-344","language":"English","title":"Human Health and Disease","topic_slug":"human-health-and-disease","definition":"Health is a state of complete physical, mental, and social well-being. It does not simply mean ''absence of disease'' or ''physical fitness''. When people are healthy, they are more efficient at work, which increases productivity and brings economic prosperity. Health also increases longevity of people and reduces infant and maternal mortality. Balanced diet, personal hygiene, and regular exercise are very important to maintain good health. Yoga has been practised since time immemorial to achieve physical and mental health. Awareness about diseases and their effect on different bodily functions, vaccination (immunisation) against infectious diseases, proper disposal of wastes, control of vectors, and maintenance of hygienic food and water resources are necessary for achieving good health. Diseases can be broadly grouped into infectious and non-infectious. Infectious diseases are easily transmitted from one person to another and are very common. Some of the infectious diseases like AIDS are fatal.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3dd' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'human-health-and-disease' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3dd-en-345","language":"English","title":"Common Diseases in Humans","topic_slug":"common-diseases-in-humans","definition":"A wide range of organisms belonging to bacteria, viruses, fungi, protozoans, helminths, etc., can cause diseases in man. Such disease-causing organisms are called pathogens. All parasites are therefore pathogens as they cause harm to the host by living in (or on) them. The pathogens can enter our body by various means, multiply, and interfere with normal vital activities, resulting in morphological and functional damage. Pathogens have to adapt to life within the environment of the host. For example, the pathogens that enter the gut must know a way of surviving in the stomach at low pH and resisting the various digestive enzymes. A few representative members from different groups of pathogenic organisms are discussed here along with the diseases caused by them.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3dd' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'common-diseases-in-humans' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3dd-en-346","language":"English","title":"Immunity","topic_slug":"immunity","definition":"The term health is very frequently used by everybody. However, the concept of health is not just the absence of disease or physical fitness. It is a state of complete physical, mental, and social well-being. The functioning of one or more organs or systems of the body is adversely affected, characterised by various signs and symptoms, we say that we are not healthy, i.e., we have a disease. The mind influences our immune system through the neural system and endocrine system, and our immune system maintains our health. Hence, mind and mental state can affect our health.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3dd' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'immunity' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3dd-en-347","language":"English","title":"AIDS","topic_slug":"aids","definition":"AIDS (Acquired Immune Deficiency Syndrome) is a fatal infectious disease caused by the Human Immunodeficiency Virus (HIV). The virus attacks the immune system and makes the body more susceptible to infections. AIDS is caused by the transmission of HIV through bodily fluids such as blood, semen, vaginal fluids, and breast milk. It can be transmitted through unprotected sex, sharing needles, and from mother to child during pregnancy, childbirth, or breastfeeding. AIDS can also be transmitted through blood transfusions and organ transplants if the blood or organs are contaminated with HIV.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3dd' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'aids' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3dd-en-348","language":"English","title":"Cancer","topic_slug":"cancer","definition":"Cancer is a non-infectious disease that occurs when the normal cells in the body grow and multiply uncontrollably. This can be due to genetic mutations or exposure to carcinogens. Cancer can be caused by various factors such as smoking, radiation, and certain chemicals. It can also be caused by genetic mutations that occur during cell division. Cancer can be treated through various methods such as surgery, chemotherapy, and radiation therapy. However, the effectiveness of these treatments depends on the stage and type of cancer.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3dd' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'cancer' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3dd-en-349","language":"English","title":"Drugs and Alcohol Abuse","topic_slug":"drugs-and-alcohol-abuse","definition":"Drug and alcohol abuse can have severe consequences on physical and mental health. It can lead to addiction, dependence, and withdrawal symptoms. Drug and alcohol abuse can also lead to various health problems such as liver disease, heart disease, and mental health disorders. It is essential to maintain a healthy lifestyle and avoid substance abuse to prevent these health problems.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3dd' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'drugs-and-alcohol-abuse' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3dd-en-350","language":"English","title":"Preventive and Control Measures","topic_slug":"preventive-and-control-measures","definition":"Maintenance of personal and public hygiene is very important for prevention and control of many infectious diseases. Measures for personal hygiene include keeping the body clean; consumption of clean drinking water, food, vegetables, fruits, etc. Public hygiene includes proper disposal of waste and excreta; periodic cleaning and disinfection of water reservoirs, pools, cesspools, and tanks, and observing standard practices.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3dd' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'preventive-and-control-measures' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d8-en-351","language":"English","title":"Human Reproduction","topic_slug":"human-reproduction","definition":"Human reproduction is a sexually reproducing and viviparous process, involving the formation of gametes (sperms in males and ovum in females), transfer of sperms into the female genital tract, and fusion of male and female gametes leading to the formation of a zygote. The process of human reproduction includes the formation and development of a blastocyst, its attachment to the uterine wall (implantation), embryonic development (gestation), and delivery of the baby (parturition). These reproductive events occur after puberty, and there are remarkable differences between the reproductive events in males and females.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d8' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'human-reproduction' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d8-en-352","language":"English","title":"The Male Reproductive System","topic_slug":"the-male-reproductive-system","definition":"The male reproductive system is located in the pelvis region and includes a pair of testes, accessory ducts, glands, and external genitalia. The testes are situated outside the abdominal cavity within a pouch called the scrotum, which helps maintain a low temperature necessary for spermatogenesis. Each testis is oval in shape, with a length of about 4 to 5 cm and a width of about 2 to 3 cm, and is covered by a dense covering.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d8' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'the-male-reproductive-system' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d8-en-353","language":"English","title":"Structure of Testis","topic_slug":"structure-of-testis","definition":"Each testis has about 200-300 testicular lobules, each containing one to three highly coiled seminiferous tubules where sperms are produced. Each seminiferous tubule is lined on its inside by two types of cells called male germ cells (spermatogonia) and Sertoli cells. The male germ cells undergo meiotic divisions, finally leading to sperm formation, while Sertoli cells provide nutrition to the germ cells.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d8' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'structure-of-testis' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d8-en-354","language":"English","title":"Male Sex Accessory Ducts","topic_slug":"male-sex-accessory-ducts","definition":"The male sex accessory ducts include rete testis, vasa efferentia, epididymis, and vas deferens. The seminiferous tubules of the testis open into the vasa efferentia through rete testis, which then lead to the epididymis. The epididymis leads to the vas deferens, which ascends to the abdomen and loops over the urinary bladder, receiving a duct from the seminal vesicle and opening into the urethra as the ejaculatory duct.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d8' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'male-sex-accessory-ducts' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d8-en-355","language":"English","title":"External Genitalia","topic_slug":"external-genitalia","definition":"The penis is the male external genitalia, made up of special tissue that helps in erection of the penis to facilitate insemination. The enlarged end of the penis is called the glans penis, which is covered by a loose fold of skin called the foreskin.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d8' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'external-genitalia' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f87822c1a19d2142de3d8-en-356","language":"English","title":"The Female Reproductive System","topic_slug":"the-female-reproductive-system","definition":"The female reproductive system consists of a pair of ovaries, a pair of oviducts, uterus, cervix, vagina, and external genitalia located in the pelvic region. The ovaries are the primary female sex organs that produce the female gamete (ovum) and several steroid hormones (ovarian hormones). Each ovary is about 2 to 4 cm in length and is connected to the pelvic wall and uterus by ligaments.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f87822c1a19d2142de3d8' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'the-female-reproductive-system' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
